--
-- Triggers `aa_battle_pass_user_mission`
--
DROP TRIGGER IF EXISTS `trg_bp_limit_before_insert`;
DELIMITER $$
CREATE TRIGGER `trg_bp_limit_before_insert` BEFORE INSERT ON `aa_battle_pass_user_mission` FOR EACH ROW BEGIN
  DECLARE v_type ENUM('daily','weekly','special');
  DECLARE v_limit INT DEFAULT 0;
  DECLARE v_cnt INT DEFAULT 0;

  
  SELECT m.type INTO v_type
  FROM aa_battle_pass_mission m
  WHERE m.id = NEW.mission_id
  LIMIT 1;

  
  IF v_type = 'daily' THEN
    SELECT COALESCE(daily_slots,2) INTO v_limit FROM aa_battle_pass_user WHERE user = NEW.user_id AND season_id = NEW.season_id LIMIT 1;
  ELSEIF v_type = 'weekly' THEN
    SELECT COALESCE(weekly_slots,1) INTO v_limit FROM aa_battle_pass_user WHERE user = NEW.user_id AND season_id = NEW.season_id LIMIT 1;
  ELSEIF v_type = 'special' THEN
    SELECT COALESCE(special_slots,1) INTO v_limit FROM aa_battle_pass_user WHERE user = NEW.user_id AND season_id = NEW.season_id LIMIT 1;
  END IF;

  
  SELECT COUNT(*) INTO v_cnt
  FROM aa_battle_pass_user_mission um
  JOIN aa_battle_pass_mission mm ON mm.id = um.mission_id
  WHERE um.user_id = NEW.user_id
    AND um.season_id = NEW.season_id
    AND um.expired = 0
    AND mm.type = v_type;

  IF v_cnt >= v_limit THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'BP limit reached for this mission type';
  END IF;
END
$$
DELIMITER ;

