INSERT INTO `base_ability` (`id`, `name`, `name_rus`, `about`) VALUES
(1, 'Adaptability', 'Адаптация', 'Увеличивает STAB эффект от атаки с 1.5 до 2.'),
(2, 'Aerilate', 'Голубая кожа', 'Меняет Нормальные атаки на Летающий тип. Также эти атаки наносят на 20% больше урона.'),
(3, 'Aftermath', 'Детонация', 'Если покемон был побежден контактной атакой противника, то противник получает урон равный 1/4 от максимального здоровья.'),
(4, 'Air Lock', 'Воздушный замок', 'Блокирует все эффекты от погоды.'),
(5, 'Analytic', 'Анализ', 'Если покемон с этой способностью атакует вторым, то мощность его атаки увеличивается на 30%.'),
(6, 'Anger Point', 'Прилив гнева', 'Если пользователь получил критический удар от атаки противника, то его Атака повысится на 6 пунктов.'),
(7, 'Anticipation', 'Предвидения', '...'),
(8, 'Arena Trap', 'Аренная ловушка', 'Способность блокирует замену противника, если только он не Призрачного типа или не левитирует. Также способность не сработает, если противник будет заменен через атаки с эффектом замены.'),
(9, 'Aroma Veil', 'Благоухание', 'Защищает союзников от ограничивающих эффектов (Провокация, Овации/Encore, Запрет/Disable, Терзания/Torment и т.п.).'),
(10, 'Aura Break', 'Разлом ауры', '...'),
(11, 'Bad Dreams', 'Кошмары', 'Пока соперник спит, в конце хода он теряет часть ОЗ.'),
(12, 'Battery', 'Аккумулятор', 'Мощность специальных атак повышается на 30%.'),
(13, 'Battle Armor', 'Боевая броня', 'Защищает покемона от критических атак противника.'),
(14, 'Battle Bond', 'Боевая связь', '...'),
(15, 'Beast Boost', 'Звериная мощь', 'Повышает покемону самый высокий стат на 1 пункт, если он одолел противника атакой, наносящей урон.\n'),
(16, 'Berserk', 'Неистовство', 'Повышает покемону Спец. Атаку, если после удара противника, его здоровье стало меньше половины от максимального.'),
(17, 'Big Pecks', 'Большой клюв', 'Способность не дает противнику понизить стат Защиты покемона в бою.'),
(18, 'Blaze', 'Яростное пламя', 'Увеличивает мощность огненных атак на 30%, если здоровье использующего меньше трети.'),
(19, 'Bulletproof', 'Пуленепробиваемость', 'Иммунитет к «снарядным» (ball/bomb) приёмам.'),
(20, 'Cacophony', 'Какофония', '...'),
(21, 'Cheek Pouch', 'Набитые щечки', 'После использование какой-либо ягоды покемон восстанавливает 1/3 часть здоровья.'),
(22, 'Chlorophyll', 'Хлорофилл', 'В солнечную погоду скорость покемонов, имеющих эту способность, увеличивается на 100%.'),
(23, 'Clear Body', 'Чистое тело', 'Предотвращает понижение параметров от эффектов соперника.'),
(24, 'Cloud Nine', 'Девятое небо', '...'),
(25, 'Color Change', 'Изменение цвета', '...'),
(26, 'Comatose', 'Бессознательность', '...'),
(27, 'Competitive', 'Соперничество', '...'),
(28, 'Compound Eyes', 'Фасеточность', 'Повышает точность приёмов примерно на 30%.'),
(29, 'Contrary', 'Порочность', 'Обращает любое воздействие на статы покемона в противоположную сторону.'),
(30, 'Corrosion', 'Коррозия', 'Яд покемона настолько силён, что преодолевает иммунитет к яду даже стальных и ядовитых покемонов.'),
(31, 'Cursed Body', 'Проклятое тело', '...'),
(32, 'Cute Charm', 'Очарование', 'Если противник использует контактную атаку, то Милый шарм с вероятность 30% может влюбить противника в пользователя.'),
(33, 'Damp', 'Влажность', 'Блокирует саморазрушающиеся приёмы (взрывы и т.п.) рядом.'),
(34, 'Dancer', 'Танцор', '...'),
(35, 'Dark Aura', 'Темная аура', '...'),
(36, 'Dazzling', 'Ослепление', '...'),
(37, 'Defeatist', 'Капитуляция', 'Статы Атаки и Спец. Атаки понижаются в 2 раза, если текущее здоровье покемона меньше (либо равно) половины от максимального.'),
(38, 'Defiant', 'Непокорность', '...'),
(39, 'Delta Stream', 'Дельта канал', '...'),
(40, 'Desolate Land', 'Пустынная земля', '...'),
(41, 'Disguise', 'Маскировка', '...'),
(42, 'Download', 'Загрузка', '...'),
(43, 'Drizzle', 'Изморось', 'Вызывает дождь при выходе на поле.'),
(44, 'Drought', 'Осушение', 'Вызывает сильное солнце при выходе на поле.'),
(45, 'Dry Skin', 'Сухая кожа', 'Иммунитет к водным атакам (без дополнительного лечения/урона от солнца в текущей реализации).'),
(46, 'Early Bird', 'Раннее пробуждение', '...'),
(47, 'Effect Spore', 'Эффект споры', '...'),
(48, 'Electric Surge', 'Электрическая волна  ', '...'),
(49, 'Emergency Exit', 'Экстренное отступление', '...'),
(50, 'Fairy Aura', 'Волшебная аура', '...'),
(51, 'Filter', 'Фильтрация', 'Блокирует 25% урона от суперэффективной атаки противника.'),
(52, 'Flame Body', 'Огненное тело', 'Если противник использует контактную атаку, то способность с вероятностью 30% может поджечь его.'),
(53, 'Flare Boost', 'Вспышка', '...'),
(54, 'Flash Fire', 'Вспышка пламени', 'Иммунитет к огненным атакам; после срабатывания усиливает собственные огненные приёмы (по механике движка).'),
(55, 'Flower Gift', 'Дар цветов', '...'),
(56, 'Flower Veil', 'Цветочный покров', '...'),
(57, 'Fluffy', 'Пушистик', '...'),
(58, 'Forecast', 'Предсказание', '...'),
(59, 'Forewarn', 'Оповещение', '...'),
(60, 'Friend Guard', 'Защита товарища', '...'),
(61, 'Frisk', 'Обыскивание', '...'),
(62, 'Full Metal Body', 'Цельнометаллическое тело', '...'),
(63, 'Fur Coat', 'Меховой плащ', 'Увеличивает стат Защиты в 2 раза.'),
(64, 'Gale Wings', 'Крылья бури', '...'),
(65, 'Galvanize', 'Гальванизировать', '...'),
(66, 'Gluttony', 'Прожорливость', '...'),
(67, 'Gooey', 'Липкость', 'Если покемон получил урон от атаки, имеющей контакт, то скорость атакующего покемона снизится на 1 пункт.'),
(68, 'Grass Pelt', 'Травяная шкура', 'Увеличивает защиту покемона на 50%, если на поле действует Травяная местность.'),
(69, 'Grassy Surge', 'Травяная волна', '...'),
(70, 'Guts', 'Сила воли', 'Если на покемоне находится какой-либо негативный статус, то его Атака увеличивается на 50%. Также покемон с этой способностью игнорирует понижение урона, когда подожжен.'),
(71, 'Harvest', 'Восстановление урожая', '...'),
(72, 'Healer', 'Исцеление', 'В начале каждого хода с 30% шансом избавляет случайного союзника от негативных статусов.'),
(73, 'Heatproof', 'Жаропрочность ', 'Снижает урон от огня/ожога по нашей механике.'),
(74, 'Heavy Metal', 'Увеличение веса ', '...'),
(75, 'Honey Gather', 'Сбор меда', '...'),
(76, 'Huge Power', 'Большая сила', 'Увеличивает стат Атаки в 2 раза.'),
(77, 'Hustle', 'Энергичность', 'Усиливает физические атаки ценой снижения точности.'),
(78, 'Hydration', 'Гидрирование', 'Во время дождя лечит покемона от Парализации, Отравления, Сна, Поджога, Заморозки.'),
(79, 'Hyper Cutter', 'Суперсильные когти', 'Предотвращает понижение параметра Атака соперником.'),
(80, 'Ice Body', 'Ледяное тело', 'Во время града покемон восстанавливает 1/16 часть здоровья. Град не будет наносить урон покемону с этой способностью.'),
(81, 'Illuminate', 'Свечение', '...'),
(82, 'Illusion', 'Иллюзия', '...'),
(83, 'Immunity', 'Иммунитет', '...'),
(84, 'Imposter', 'Самозванец', '...'),
(85, 'Infiltrator', 'Проскальзывание', 'Маленькие размеры и природная юркость позволяют покемону игнорировать любые защитные сооружения противника (Защитный экран, Экран света, Ограждение, Туман, Приманка).'),
(86, 'Innards Out', 'Наизнанку', '...'),
(87, 'Inner Focus', 'Концентрация', 'Защищает от испуга (flinch).'),
(88, 'Insomnia', 'Бессонница', 'Покемон не может уснуть.'),
(89, 'Intimidate', 'Яростный взгляд', 'При выходе на поле понижает Атаку соперника.'),
(90, 'Iron Barbs', 'Железные шипы', 'Противник получает урон от 1/8 части максимального здоровья, если он нанес урон контактной атакой покемону с этой способностью.'),
(91, 'Iron Fist', 'Железный кулак', 'Мощность атак-кулаков увеличивается на 20%.'),
(92, 'Justified', 'Сердце правосудия', 'Если покемон получил урон от темной атаки противника, то он увеличивает свою Атаку на 1 пункт.'),
(93, 'Keen Eye', 'Острый глаз', 'Небывалая зоркость позволяет покемону избежать снижения своей Точности и игнорировать повышения Ловкости противника.'),
(94, 'Klutz', 'Неуклюжесть ', '...'),
(95, 'Leaf Guard', 'Травяной щит', '...'),
(96, 'Levitate', 'Левитация', 'Иммунитет к Земным атакам и шипам, зависящим от касания земли.'),
(97, 'Light Metal', 'Снижение веса ', '...'),
(98, 'Lightning Rod', 'Громоотвод ', 'Иммунитет к Электрическим атакам; такие атаки перенаправляются на обладателя (рост Сп.Атаки — если включён движком).'),
(99, 'Limber', 'Гибкость', '...'),
(100, 'Liquid Ooze', 'Жидкая грязь', '...'),
(101, 'Liquid Voice', 'Плавный голос', '...'),
(102, 'Long Reach', 'Большой обхват', '...'),
(103, 'Magic Bounce', 'Волшебное зеркало ', '...'),
(104, 'Magic Guard', 'Волшебный щит', '...'),
(105, 'Magician', 'Чародейство', '...'),
(106, 'Magma Armor', 'Магмовая броня', '...'),
(107, 'Magnet Pull', 'Магнитное притяжение', '...'),
(108, 'Marvel Scale', 'Чудесная чешуя', 'Повышает защиту покемона на 50%, если под действием какого-либо из этих статусов: Спит, Подожжен, Парализован, Отравлен, Заморожен.'),
(109, 'Mega Launcher', 'Мега-пушка', 'Усиливает восстановление ОЗ от собственных приёмов лечения.'),
(110, 'Merciless', 'Беспощадность', 'Покемон, стараясь быстрее избавить отравленного противника от страданий, наносит только критические удары.'),
(111, 'Minus', 'Минус', '...'),
(112, 'Misty Surge', 'Туманная волна', '...'),
(113, 'Mold Breaker', 'Разрыв шаблона', 'Игнорирует мешающие способности цели при атаке.'),
(114, 'Moody', 'Переменчивое настроение ', '...'),
(115, 'Motor Drive', 'Разогрев мотора', 'Покемон повышает Скорость на 1 пункт, если его ударили электрической атакой. Также этот полученный урон становится нулевым.'),
(116, 'Moxie', 'Ловкость', 'Повышает покемону атаку на 1 пункт, если он одолел противника атакой, наносящей урон.'),
(117, 'Multiscale', 'Мульти-чешуя ', '...'),
(118, 'Multitype', 'Мультитип', '...'),
(119, 'Mummy', 'Мумия', '...'),
(120, 'Natural Cure', 'Естественное исцеление', 'При возврате в резерв излечивает большинство статус-эффектов.'),
(121, 'Neuroforce', 'Нейросила', '...'),
(122, 'No Guard', 'Боец-одиночка', 'Всегда попадают и ваши приёмы, и приёмы по вам (true hit).'),
(123, 'Normalize', 'Нормализация ', '...'),
(124, 'Oblivious', 'Забвение', '...'),
(125, 'Overcoat', 'Пыленепроницаемость', 'Иммунитет к порошковым приёмам; также игнорирует урон/эффекты погоды.'),
(126, 'Overgrow', 'Сверхрост', 'Увеличивает мощность травяных атак на 30%, если здоровье использующего меньше трети.'),
(127, 'Own Tempo', 'Собственный темп', 'Покемон с этой способностью не может быть спутан.'),
(128, 'Parental Bond', 'Родительская связь', '...'),
(129, 'Pickpocket', 'Карманный вор ', '...'),
(130, 'Pickup', 'Сбор предметов', 'После битвы покемон с некоторым шансом может найти какой-либо предмет.'),
(131, 'Pixilate', 'Чудесная кожа', '...'),
(132, 'Plus', 'Плюс', '...'),
(133, 'Poison Heal', 'Токсифаг', 'Пока отравлен, вместо урона получает восстановление ОЗ каждый ход.'),
(134, 'Poison Point', 'Ядовитые колючки', 'Если противник использует контактную атаку, то Ядовитая кожа с вероятность 30% может отравить противника.'),
(135, 'Poison Touch', 'Ядовитое касание', '...'),
(136, 'Power Construct', 'Мощное строение', '...'),
(137, 'Power of Alchemy', 'Сила алхимии', '...'),
(138, 'Prankster', 'Проказник', 'Увеличивает приоритет статусных атак на 1 пункт.'),
(139, 'Pressure', 'Давление', 'Противник теряет дополнительное 1 PP атаки.'),
(140, 'Primordial Sea', 'Изначальное море', '...'),
(141, 'Prism Armor', 'Призменный доспех ', '...'),
(142, 'Protean', 'Изменчивость ', '...'),
(143, 'Psychic Surge', 'Психическая волна', '...'),
(144, 'Pure Power', 'Чистая сила', '...'),
(145, 'Queenly Majesty', 'Величие', '...'),
(146, 'Quick Feet', 'Быстрые ноги', 'Увеличивает скорость на 50% если покемон имеет отрицательный статус. Кроме того, покемон не теряет скорость, если он парализован.'),
(147, 'Rain Dish', 'Омывка дождем', 'Во время дождя в конце каждого хода покемон восстанавливает 1/8 часть здоровья.'),
(148, 'Rattled', 'Нервозность', 'Покемон увеличивает свою Скорость на 1 пункт, если против него успешно использовали атаки Насекомого/Призрачного/Темного типа.'),
(149, 'Receiver', 'Приемник', '...'),
(150, 'Reckless', 'Опрометчивость ', 'Увеличивает мощность атак, имеющих отдачу, на 20%.'),
(151, 'Refrigerate', 'Охлаждение', '...'),
(152, 'Regenerator', 'Регенерация', '...'),
(153, 'Rivalry', 'Соперничество ', 'Покемон в естественной среде обитания привык жить в стаях. Соперничество с целью продолжения рода у него глубоко в генах. В сражениях с противником своего пола мощность атак увеличивается на 25%, противоположенного - уменьшается на 25%.'),
(154, 'RKS System', 'Система RKS', 'Покемон является носителем комбинированного гена и меняет свой тип в зависимости от предмета, который он держит.'),
(155, 'Rock Head', 'Каменная голова', 'Ваш покемон не получает урон от отдачи после использования своих атак.'),
(156, 'Rough Skin', 'Грубая кожа', 'Противник получает урон от 1/8 части максимального здоровья, если он нанес урон контактной атакой покемону с этой способностью.'),
(157, 'Run Away', 'Бегство', 'Бой заканчивается вничью, так как покемон убегает с этой битвы. Работает только в PVE.'),
(158, 'Sand Force', 'Сила песка', 'Предотвращает урон от песка в песчаную бурю. Способность также увеличивает мощность Стальных, Земляных и Каменных атак на 30% в песчаную бурю.'),
(159, 'Sand Rush', 'Песчаная гонка', 'Удачное строение лап позволяет покемону быстро перемещаться по песку - при возникновении песчаной бури Скорость удваивается и покемон не испытывает повреждений от песка'),
(160, 'Sand Stream', 'Пробуждение песков  ', 'Вызывает песчаную бурю при выходе на поле.'),
(161, 'Sand Veil', 'Песчаный покров', 'В песчаной буре по обладателю труднее попасть (снижение точности противника по нашей механике).'),
(162, 'Sap Sipper', 'Поглотитель соков', 'Иммунитет к Травяным атакам; при попадании Атака повышается на 1.'),
(163, 'Schooling', 'Стая', '...'),
(164, 'Scrappy', 'Дерзость', 'Покемон с этой способностью может наносить урон призрачным покемонам боевыми и нормальными атаками.'),
(165, 'Serene Grace', 'Небесное благословение', 'Удваивает шанс дополнительного эффекта приёмов.'),
(166, 'Shadow Shield', 'Темный щит', '...'),
(167, 'Shadow Tag', 'Тёмная метка', 'Не позволяет противнику покинуть поле боя обычной сменой покемона, кроме случаев, когда у него тип Призрак или способность Левитация. Не действует против покемонов с Темной меткой.'),
(168, 'Shed Skin', 'Сбрасывание кожи', 'С 33% шансом избавляет покемона от Парализации, Отравления, Сна, Заморозки и Поджога в конце раунда.'),
(169, 'Sheer Force', 'Грубая сила', '...'),
(170, 'Shell Armor', 'Панцирь-броня', 'Защищает покемона от критических атак противника.'),
(171, 'Shield Dust', 'Защитная пыльца', '...'),
(172, 'Shields Down', 'Беззащитность ', '...'),
(173, 'Simple', 'Простота', '...'),
(174, 'Skill Link', 'Развитие навыка', 'Покемон гарантировано попадет всеми пяти атаками, которые наносят урон 2-5 раз за ход.'),
(175, 'Slow Start', 'Медленный старт', '...'),
(176, 'Slush Rush', 'Грязевой натиск', 'Скорость покемона удваивается в град.'),
(177, 'Sniper', 'Снайпер', 'Критические удары теперь будут наносить x2.25 урона вместо x1.5.'),
(178, 'Snow Cloak', 'Снежные покровы', '...'),
(179, 'Snow Warning', 'Снежная тревога', 'Вызывает снегопад при выходе на поле.'),
(180, 'Solar Power', 'Солнечная сила', 'В солнечную погоду Спец. Атака покемона повышена на 50%. Покемон также получает 1/8 часть урона в конце каждого раунда.'),
(181, 'Solid Rock', 'Твердый камень', '...'),
(182, 'Soul-Heart', 'Единство', '...'),
(183, 'Soundproof', 'Звуконепроницаемость', 'Иммунитет ко всем звуковым приёмам.'),
(184, 'Speed Boost', 'Ускорение', 'В конце хода увеличивает Скорость на 1 пункт.'),
(185, 'Stakeout', 'Надзор', '...'),
(186, 'Stall', 'Задерживание ', '...'),
(187, 'Stamina', 'Выносливость', 'Когда покемон с этой способностью поражается атакой противника, его Защита повышается на 1 пункт.'),
(188, 'Stance Change', 'Королевское построение', 'Меняет форму в зависимости от типа применяемого приёма.'),
(189, 'Static', 'Статическое электричество', 'Если противник использует контактную атаку, то способность с вероятностью 30% может парализовать его. Срабатывает и на земляных покемонов.'),
(190, 'Steadfast', 'Неукротимость', 'Повышает Скорость пользователя на 1 пункт, если он не смог атаковать в этот ход из-за испуга.'),
(191, 'Steelworker', 'Сталевар', 'Увеличивает мощность стальных атак на 50%.'),
(192, 'Stench', 'Зловоние', '...'),
(193, 'Sticky Hold', 'Липкий захват', '...'),
(194, 'Storm Drain', 'Водоотвод', '...'),
(195, 'Strong Jaw', 'Крепкая челюсть ', 'Увеличивает мощность атак с Укусом на 50%.'),
(196, 'Sturdy', 'Стойкость', 'Покемон способен выдержать любую направленную атаку, сохранив минимум 1 очко здоровья. Способность активируется лишь в том случае, если перед атакой противника у пользователя было максимальное здоровье.'),
(197, 'Suction Cups', 'Присоски', '...'),
(198, 'Super Luck', 'Сверхудачливость', 'Увеличивает шанс нанести критический урон на 10%.'),
(199, 'Surge Surfer', 'Серфер', '...'),
(200, 'Swarm', 'Роение', 'Когда очки здоровья покемона ниже трети от максимума, он использует инстинкты выживания в рое, повышая мощность атак с типом насекомое на 50%.'),
(201, 'Sweet Veil', 'Сладкий покров', '...'),
(202, 'Swift Swim', 'Быстрое плавание', 'В дождь Скорость покемона удваивается.'),
(203, 'Symbiosis', 'Симбиоз', '...'),
(204, 'Synchronize', 'Синхронизация', 'При получении основного статуса передаёт его противнику (если тот не иммунен).'),
(205, 'Tangled Feet', 'Косолапость', 'Пока покемон в замешательстве, по нему труднее попасть (снижается точность противника).'),
(206, 'Tangling Hair', 'Запутанные волосы', '...'),
(207, 'Technician', 'Техничность', 'Пытаясь сбалансировать силу атак, покемон увеличивает на 50% мощность атак, базовая сила которых 60 и менее.'),
(208, 'Telepathy', 'Телепатия', '...'),
(209, 'Teravolt', 'Теравольт', '...'),
(210, 'Thick Fat', 'Жировой запас', 'Толстый слой подкожного жира спасает покемон от воздействия критических температур, снижая урон от Ледяных и Огненных атак на 50%.'),
(211, 'Tinted Lens', 'Тонированные линзы', 'Уникальное строение глазных линз покемона помогает находить ему уязвимые места противника, что помогает наносить обычный урон вместо малоэффективных атак.'),
(212, 'Torrent', 'Всплеск', 'Увеличивает мощность водных атак на 50%, если здоровье использующего меньше трети.'),
(213, 'Tough Claws', 'Крепкие когти', 'Увеличивает мощность атак, вступающих в контакт, на 30%.'),
(214, 'Toxic Boost', 'Ярость от отравления', 'Мощность физических атак покемона увеличивается на 50%, если он отравлен.'),
(215, 'Trace', 'Слежка', '...'),
(216, 'Triage', 'Сортировка', 'Некоторые атаки с лечением имеют приоритет +3.'),
(217, 'Truant', 'Ленивость', 'Из-за лени, покемон после атаки, отдыхает один ход. Менять покемонов и использовать предметы в ход, когда покемон отдыхает, можно.'),
(218, 'Turboblaze', 'Турбопламя', '...'),
(219, 'Unaware', 'Безразличие', 'Игнорирует боевые модификаторы характеристик цели.'),
(220, 'Unburden', 'Освобождение ', '...'),
(221, 'Unnerve', 'Нервирование', 'Заставляет противника нервничать, что мешает съесть ягоду которую он держит.'),
(222, 'Victory Star', 'Звезда победы', 'Точность всех атак вашей стороны повышается на 10%.'),
(223, 'Vital Spirit', 'Подъём духа', '...'),
(224, 'Volt Absorb', 'Поглощение электричества', 'Иммунитет к электрическим атакам (в нашей механике: ход цели не срабатывает по обладателю).'),
(225, 'Water Absorb', 'Поглощение воды', 'Иммунитет к водным атакам (в нашей механике: ход цели не срабатывает по обладателю).'),
(226, 'Water Bubble', 'Водный пузырь', 'Защищает от ожога.'),
(227, 'Water Compaction', 'Водное уплотнение ', '...'),
(228, 'Water Veil', 'Мокрая шкура', 'Под сильным солнцем предотвращает большинство статус-эффектов.'),
(229, 'Weak Armor', 'Слабая броня', 'После удачной физической атаки покемон повышает Скорость на 2 пункта, но Защита понижается на 1 пункт.'),
(230, 'White Smoke', 'Белый дым', '...'),
(231, 'Wimp Out', 'Трусливость', '...'),
(232, 'Wonder Guard', 'Чудесный щит', 'Блокирует любой прямой урон от атаки, если она не суперэффективная.'),
(233, 'Wonder Skin', 'Призрачная кожа', '...'),
(234, 'Zen Mode', 'Режим дарумы ', '...'),
(235, 'Libero', 'Либеро', '...'),
(236, 'Mirror Armor', 'Зеркальная броня', 'Блокирует и отражает в противника нежелательные понижения характеристик.'),
(237, 'Steam Engine', 'Паровой двигатель', 'При получении урона от атаки Огненного или Водного типа, стат Скорости этого покемона повышается на 6 пунктов.'),
(238, 'Sand Spit', 'Песчаный всплеск', 'Если покемона ударили наносящей урон атакой, он вызывает Песчаную бурю.'),
(239, 'Propeller Tail', 'Хвост-пропеллер', '...'),
(240, 'Punk Rock', 'Панк-рок', 'Этот покемон получает на 50% меньше урона от звуковых атак. Способность увеличивает мощность звуковых атак этого покемона на 30%.'),
(241, 'Wandering Spirit', 'Блуждающий дух', '...'),
(242, 'Neutralizing Gas', 'Нейтрализующий газ', '...'),
(243, 'Cotton Down', 'Сброс хлопка', 'Если покемона ударили контактной атакой, Скорость противника понижается на 1.'),
(244, 'Ball Fetch', 'Игра в мячик', '...'),
(245, 'Ripen', 'Созревание', '...'),
(246, 'Gulp Missile', 'Непроглоченный снаряд', '...'),
(247, 'Steely Spirit', 'Стальной дух', 'У покемона увеличивается базовая мощность стальных атак на 35%.'),
(248, 'Perish Body', 'Последнее касание', 'Контакт с этим покемонов запускает для него и атакующего эффект Скорбная песнь.'),
(249, 'Screen Cleaner', 'Очиститель экранов', 'При выходе на поле снимает Световой экран, Отражение и Полярное сияние со всех сторон.'),
(250, 'Ice Scales', 'Ледяные чешуйки', 'Покемон получает на 50% меньше урона от специальных атак.'),
(251, 'Power Spot', 'Место силы', '...'),
(252, 'Ice Face', 'Ледяное лицо', '...'),
(253, 'Hunger Switch', 'Непостоянный голод', '...'),
(254, 'Stalwart', 'Настойчивость', '...'),
(255, 'Intrepid Sword', 'Отважный мечник', 'Входя в бой, покемон повышает свой стат Атаки на 1 пункт.'),
(256, 'Dauntless Shield', 'Бесстрашный защитник', 'Входя в бой, покемон повышает свой стат Защиты на 1 пункт.'),
(257, 'Unseen Fist', 'Невидимый кулак', '...'),
(258, 'Transistor', 'Транзистор', 'Увеличивает мощность электрических атак на 50%.'),
