INSERT INTO `base_atk` (`id`, `name`, `name_rus`, `settings`, `my`, `enemy`, `title`, `type`, `category`, `priority`, `power`, `accuracy`, `pp`, `target`, `contact`, `mechanics`, `tech`, `title_all`, `pulse`, `mod`, `status`, `sound`, `punch`, `bite`, `snatchable`, `magic_coat`, `protect`, `mirror_move`, `bullet`) VALUES
(1, 'Absorb', 'Поглощение', NULL, '{\"heal_dmg\":0.5}', NULL, 'Покемон устремляется к противнику, прикасается к нему и высасывает небольшое количество жизненной силы, временно паразитируя на противнике. Половина отнятых у соперника НР преобразуются в собственные.', 'grass', 'special', 0, 20, 100, 15, 'enemy', 0, 'Половина отнятых у соперника НР преобразуются в собственные.', '<font color=green>Атака работает исправно</font>', '', 0, '', '', 0, 0, 0, 0, 0, 1, 1, 0),
(2, 'Acid', 'Кислота', NULL, NULL, '{\"stats\":[[\"sdef\",1,\"minus\",10]]}', 'Покемон выпускает струю кислоты, способной проесть почти любую броню. Спец.Защита противника -1 (10% шанс).', 'poison', 'special', 0, 40, 100, 30, 'enemy', 0, 'Понижает Спец.Защиту противника на 1 уровень с шансом 10%.', '<font color=green>Атака работает исправно</font>', '', 0, '', '', 0, 0, 0, 0, 0, 1, 1, 0),
(3, 'Acid Armor', 'Ядовитый доспех', NULL, '{\"stats\":[\r\n[\"def\",2,\"plus\"]\r\n]}', NULL, 'Покемон покрывает себя тонкой ядовитой пленкой. Противник, опасаясь губительного действия яда, атакует не в полную силу.', 'poison', 'status', 0, 0, 0, 20, 'me', 0, 'Повышает Защиту пользователя на 2 уровня.', '<font color=green>Атака работает исправно</font>', '', 0, '', '', 0, 0, 0, 1, 0, 0, 0, 0),
(4, 'Acid Spray', 'Кислотное распыление', NULL, NULL, '{     \"stats\":[         [\"sdef\", 2, \"minus\", 100]     ] }', 'Имеет 100% вероятность понизить Спец. Защиту цели на две ступени.', 'poison', 'special', 0, 40, 100, 20, 'enemy', 0, 'Нет дополнительных эффектов', '<font color=green>Атака работает исправно</font>', '', 0, '', '', 0, 0, 0, 0, 0, 1, 0, 1),
(5, 'Acrobatics', 'Акробатика', NULL, NULL, NULL, 'Сила атаки удваивается, если покемон не держит предмета. Если покемон держит Летанит, предмет используется до проверки атакой его наличия; таким образом, сила атаки утраивается.', 'fly', 'physical', 0, 55, 100, 15, 'enemy', 1, 'Нет дополнительных эффектов', '<font color=green>Атака работает исправно</font>', '', 0, '', '', 0, 0, 0, 0, 0, 1, 0, 0),
(6, 'Acupressure', 'Точечный массаж', NULL, NULL, NULL, 'Повышает случайную характеристику пользователя на 2 ступени.', 'normal', 'status', 0, 0, 0, 30, 'me', 0, 'Нет дополнительных эффектов', '<font color=green>Атака работает исправно</font>', '', 0, '', '', 0, 0, 0, 0, 0, 0, 0, 0),
(7, 'Aerial Ace', 'Воздушная грация', '{\"truehit\":1}', NULL, NULL, 'Игнорирует модификаторы точности и уклонения.', 'fly', 'physical', 0, 60, 100, 20, 'enemy', 1, 'Нет дополнительных эффектов', '<font color=green>Атака работает исправно</font>', '', 0, '', '', 0, 0, 0, 0, 0, 1, 0, 0),
(8, 'Aeroblast', 'Воздушный взрыв', '{\"chance_critical\":1}', NULL, NULL, 'Шанс критического удара на одну ступень выше обычного.', 'fly', 'special', 0, 100, 95, 5, 'enemy', 0, 'Нет дополнительных эффектов', '<font color=green>Атака работает исправно</font>', '', 0, '', '', 0, 0, 0, 0, 0, 1, 0, 0),
(9, 'After You', 'После вас', NULL, NULL, NULL, 'Цель этой атаки ходит сразу же после её использования, вне зависимости от приоритета её атаки.', 'normal', 'status', 0, 0, 100, 15, 'ally', 0, 'Нет дополнительных эффектов', '<font color=green>Атака работает исправно</font>', '', 0, '', '', 0, 0, 0, 0, 0, 0, 0, 0),
(10, 'Agility', 'Ускорение', NULL, '{\"stats\":[\r\n\r\n[\"spd\",2,\"plus\"]\r\n\r\n]}', NULL, 'Повышает свою Скорость на две ступени.', 'psychic', 'status', 0, 0, 100, 30, 'me', 0, 'Нет дополнительных эффектов', '<font color=green>Атака работает исправно</font>', '', 0, '', '', 0, 0, 0, 1, 0, 0, 0, 0),
(11, 'Air Cutter', 'Воздушный разрез', '{\"chance_critical\":1}', NULL, NULL, 'Имеет повышенный шанс критического удара.', 'fly', 'special', 0, 60, 95, 25, 'enemy', 0, 'Нет дополнительных эффектов', '<font color=green>Атака работает исправно</font>', '', 0, '', '', 0, 0, 0, 0, 0, 1, 0, 0),
(12, 'Air Slash', 'Воздушное лезвие', NULL, NULL, '{\"status\":[[\"30\", \"flinch\", 1, \"\"]]}', 'Имеет 30% вероятность заставить цель дрогнуть.', 'fly', 'special', 0, 75, 95, 15, 'enemy', 0, 'Нет дополнительных эффектов', '<font color=green>Атака работает исправно</font>', '', 0, '', '', 0, 0, 0, 0, 0, 1, 0, 0),
(13, 'Ally Switch', 'Перестановка', NULL, NULL, NULL, 'Меняется местами с союзником на противоположной стороне поля. НЕ РАБОТАЕТ ИЗ-ЗА ОТСУТСТВИЯ ДВОЙНЫХ БОЕВ\r\n', 'psychic', 'status', 2, 0, 100, 15, 'ally', 0, 'Нет дополнительных эффектов', '<font color=green>Атака работает исправно</font>', '', 0, '', '', 0, 0, 0, 0, 0, 0, 0, 0),
(14, 'Amnesia', 'Амнезия', NULL, '{\"stats\":[\r\n\r\n[\"sdef\",2,\"plus\"]\r\n\r\n]}', NULL, 'Повышает свою Спец. Защиту на две ступени.', 'psychic', 'status', 0, 0, 100, 20, 'me', 0, 'Нет дополнительных эффектов', '<font color=green>Атака работает исправно</font>', '', 0, '', '', 0, 0, 0, 1, 0, 0, 0, 0),
