(16, 'Aqua Jet', 'Водная струя', NULL, NULL, NULL, 'Наносит обычные повреждения без дополнительных эффектов, кроме приоритета.', 'water', 'physical', 1, 40, 100, 20, 'enemy', 1, 'Нет дополнительных эффектов', '<font color=green>Атака работает исправно</font>', '', 0, '', '', 0, 0, 0, 0, 0, 1, 0, 0),
(17, 'Aqua Ring', 'Водное кольцо', NULL, NULL, NULL, 'Восстанавливает 1/16 своих максимальных ОЗ в конце каждого хода.', 'water', 'status', 0, 0, 100, 20, 'me', 0, 'Нет дополнительных эффектов', '<font color=green>Атака работает исправно</font>', '', 0, '', '', 0, 0, 0, 0, 0, 0, 0, 0),
(18, 'Aqua Tail', 'Водный хвост', NULL, NULL, NULL, 'Наносит обычные повреждения без дополнительных эффектов.', 'water', 'physical', 0, 90, 90, 10, 'enemy', 1, 'Нет дополнительных эффектов', '<font color=green>Атака работает исправно</font>', '', 0, '', '', 0, 0, 0, 0, 0, 1, 0, 0),
(19, 'Arm Thrust', 'Выпад ладони', '{\"count_hit\":[2,5]}', NULL, NULL, 'Наносит 2-5 ударов за ход.', 'fighting', 'physical', 0, 15, 100, 20, 'enemy', 0, 'Нет дополнительных эффектов', '<font color=green>Атака работает исправно</font>', '', 0, '', '', 0, 0, 0, 0, 0, 1, 0, 0),
(20, 'Aromatherapy', 'Ароматерапия', NULL, '{\"clear_status_all_poke\":[\"toxic\",\"toxic2\",\"paralyzed\",\"sleep\",\"burn\",\"frost\"]}', NULL, 'Исцеляет всю команду от основных проблем состояния.', 'grass', 'status', 0, 0, 0, 5, 'all_me', 0, 'Нет дополнительных эффектов', '<font color=green>Атака работает исправно</font>', '', 0, '', '', 0, 0, 0, 0, 0, 0, 0, 0),
(22, 'Assist', 'Помощь', NULL, NULL, NULL, 'Случайным образом выбирает и использует одну из атак остальных покемонов в команде.', 'normal', 'status', 0, 0, 100, 20, 'me', 0, 'Нет дополнительных эффектов', '<font color=green>Атака работает исправно</font>', '', 0, '', '', 0, 0, 0, 0, 0, 0, 0, 0),
