(508, 0, 'Желе', NULL, 'quest', NULL, 'Мягкое ягодное желе.', 10, 0, 'false', 'false', 'true', 'true', 'false', 'true', 0, NULL, '0', 0, 0, '', '', 0, '<span>Нечастая награда</span>', 'normal', '0', NULL, NULL, NULL),
(509, 0, 'Угощение для Абамасноу', NULL, 'quest', NULL, 'Редкое лакомство которое имеет целительные свойства и особенно нравится травяным и снежным покемонам', 10, 0, 'false', 'false', 'true', 'true', 'false', 'true', 0, NULL, '0', 0, 0, '', '', 0, '<span>Нечастая награда</span>', 'normal', '0', NULL, NULL, NULL),
(510, 0, 'Лепестки Бурми', NULL, 'quest', NULL, 'Лепестки лекаря. Редко можно найти рядом с покемоном Бурми.', 10, 0, 'false', 'false', 'true', 'true', 'false', 'true', 0, NULL, '0', 0, 0, '', '', 0, '<span>Нечастая награда</span>', 'normal', '0', NULL, NULL, NULL),
(511, 0, 'Лепестки Оддиша', NULL, 'quest', NULL, 'Лепестки лекаря. Редко можно лайти рядом с покемоно Оддиш.', 10, 0, 'false', 'false', 'true', 'true', 'false', 'true', 0, NULL, '0', 0, 0, '', '', 0, '<span>Нечастая награда</span>', 'normal', '0', NULL, NULL, NULL),
(512, 0, 'Ягодный торт', NULL, 'quest', NULL, 'Самый большой и вкусный торт с ягодами и шоколадом.', 10, 0, 'false', 'false', 'true', 'true', 'false', 'true', 0, NULL, '0', 0, 0, '', '', 0, '<span>Нечастая награда</span>', 'normal', '0', NULL, NULL, NULL),
(513, 0, 'Заготовочный диск', NULL, 'craft', NULL, 'Чистый компакт-диск на который можно записать практически любую информацию по ТМ или TR атаке.', 10, 0, 'false', 'false', 'true', 'true', 'false', 'true', 0, NULL, '0', 0, 0, '', '', 0, '<span>Нечастая награда</span>', 'rare', '0', NULL, NULL, NULL),
(514, 0, 'Еловая ветка', NULL, 'quest', NULL, 'Ветка, содержащая частичку Нового Года.', 10, 0, 'false', 'false', 'true', 'false', 'false', 'false', 0, NULL, '0', 0, 0, '', '', 0, '<span>Нечастая награда</span>', 'normal', '0', NULL, NULL, NULL),
(515, 0, 'Карамель', NULL, 'craft', NULL, 'Продукт, полученный в результате варки сахара. В холодном состоянии она желтого или светло-коричневого цвета, при ударе рассыпается на кристаллы и не липнет к зубам. Применяется для изготовления конфет, монпансье, леденцов, и других кондитерских изделий.', 10, 0, 'false', 'false', 'true', 'true', 'false', 'true', 0, NULL, '0', 0, 0, '', '', 0, '<span>Нечастая награда</span>', 'normal', '0', NULL, NULL, NULL),
(516, 0, 'Заряженная сфера', NULL, 'craft', NULL, 'Сфера небольшого размера заряженная электрическим током, предназначена для подзарядки электро приборов и покемонов электрического типа , если у тех недостаточно сил.', 10, 0, 'false', 'false', 'true', 'true', 'false', 'true', 0, NULL, '0', 0, 0, '', '', 0, '<span>Нечастая награда</span>', 'normal', '0', NULL, NULL, NULL),
(517, 0, 'Перец Чили', NULL, 'craft', NULL, 'Среди всех известных видов стручкового перца Чили самый жгучий. Он очень любим среди покемонов огненного типа, но не все могут стерпеть его остроту и пряность, даже легкое прикосновение к нему может вызвать жжение и боль.', 10, 0, 'false', 'false', 'true', 'true', 'false', 'true', 0, NULL, '0', 0, 0, '', '', 0, '<span>Нечастая награда</span>', 'normal', '0', NULL, NULL, NULL),
(518, 0, 'Загуститель', NULL, 'craft', NULL, 'Загустители улучшают и сохраняют структуру пищевого продукта, позволяют получать продукты с нужной консистенцией, которое положительно влияет на вкусовое восприятие изделия.', 10, 0, 'false', 'false', 'true', 'true', 'false', 'true', 0, NULL, '0', 0, 0, '', '', 0, '<span>Нечастая награда</span>', 'normal', '0', NULL, NULL, NULL);
INSERT INTO `base_items` (`id`, `cool`, `name`, `skinName`, `type`, `sex`, `about`, `categories`, `weight`, `give`, `dress`, `drop`, `trade`, `use`, `lombard`, `battle`, `info`, `str`, `news`, `tm_id`, `nameEng`, `descriptionEng`, `expiration`, `drop_it`, `rait_it`, `craft`, `skin_id`, `skin_color`, `skin_form`) VALUES
(519, 0, 'Макадамия', NULL, 'craft', NULL, 'Орех имеет сладковатый вкус и считается деликатесом, он выращивается на специальных плантациях , но парой такие деревья можно найти в лесах, только вот сам орех будет сложно достать, уж очень сильно его любят покемоны каменного типа.', 10, 0, 'false', 'false', 'true', 'true', 'false', 'true', 0, NULL, '0', 0, 0, '', '', 0, '<span>Нечастая награда</span>', 'normal', '0', NULL, NULL, NULL),
(520, 0, 'Блестящая пыльца', NULL, 'craft', NULL, 'Пыльца предназначена для декорирования поверхности кондитерских и хлебобулочных изделий, десертов и фруктов. Придает поверхности блестящее мерцающее покрытие и очень сильно привлекает волшебных покемонов.', 10, 0, 'false', 'false', 'true', 'true', 'false', 'true', 0, NULL, '0', 0, 0, '', '', 0, '<span>Нечастая награда</span>', 'normal', '0', NULL, NULL, NULL),
(521, 0, 'Кофеин', NULL, 'craft', NULL, 'Является психоактивным веществом, содержится в кофе, чае, матче, входит в состав энергетиков и многих прохладительных напитков. Также входит в состав аптечных препаратов. Снижает усталость, повышает внимание и настроение.', 10, 0, 'false', 'false', 'true', 'true', 'false', 'true', 0, NULL, '0', 0, 0, '', '', 0, '<span>Нечастая награда</span>', 'normal', '0', NULL, NULL, NULL),
(522, 0, 'Рыбья чешуйка', NULL, 'craft', NULL, 'Эта блестящая пластинка очень похожа на пайетку, имеющая небольшой изгиб и за счёт этого создающая эффект объема. В чешуе содержится большое количество белка и минеральных веществ, а ещё они забавно хрустят. Обычно покемоны драконьего типа предпочитают это лакомство, ведь оно схоже с их обычным рационом.', 10, 0, 'false', 'false', 'true', 'true', 'false', 'true', 0, NULL, '0', 0, 0, '', '', 0, '<span>Нечастая награда</span>', 'normal', '0', NULL, NULL, NULL),
(523, 0, 'Флакон родниковой воды', NULL, 'craft', NULL, 'Флакон небольшого размера содержит в тебе чистейшую родниковую воду, в ней нет мусора или примесей, только прозрачная охлаждающая жидкость.', 10, 0, 'false', 'false', 'true', 'true', 'false', 'true', 0, NULL, '0', 0, 0, '', '', 0, '<span>Нечастая награда</span>', 'normal', '0', NULL, NULL, NULL),
(524, 0, 'Мята', NULL, 'craft', NULL, 'Многолетнее корневищное травянистое растение с характерным сильным запахом и холодящим вкусом. Добавляется в множество кондитерских изделий и лекарств.', 10, 0, 'false', 'false', 'true', 'true', 'false', 'true', 0, NULL, '0', 0, 0, '', '', 0, '<span>Нечастая награда</span>', 'normal', '0', NULL, NULL, NULL),
(525, 0, 'Зефирка', NULL, 'craft', NULL, 'Одна из самых популярных кондитерских изделий, которое в классическом варианте готовится из яичных белков, яблочной пастилы или агар-агара. Зефир- это кладезь сахарозы и лактозы, так необходимых спортсменам и в особенности летунам.', 10, 0, 'false', 'false', 'true', 'true', 'false', 'true', 0, NULL, '0', 0, 0, '', '', 0, '<span>Нечастая награда</span>', 'normal', '0', NULL, NULL, NULL),
(526, 0, 'Конфета с могилы', NULL, 'craft', NULL, 'Конфеты предназначенные для поминания усопших, очень сильно привлекают призрачных покемонов.', 10, 0, 'false', 'false', 'true', 'true', 'false', 'true', 0, NULL, '0', 0, 0, '', '', 0, '<span>Нечастая награда</span>', 'normal', '0', NULL, NULL, NULL),
(527, 0, 'Просроченная глазурь', NULL, 'craft', NULL, 'Такая глазурь в массовом производстве не используется так как это чревато последствиями. Но в утиль она тоже не идёт, ей нашли применение в укращении ядовитых покемонов.', 10, 0, 'false', 'false', 'true', 'true', 'false', 'true', 0, NULL, '0', 0, 0, '', '', 0, '<span>Нечастая награда</span>', 'normal', '0', NULL, NULL, NULL),
(528, 0, 'Цветок ромашки', NULL, 'craft', NULL, 'Цветок состоит из жёлтой середины и белых продолговатых лепестков. Он похож на маленькое солнышко или на зонтик.', 10, 0, 'false', 'false', 'true', 'true', 'false', 'true', 0, NULL, '0', 0, 0, '', '', 0, '<span>Нечастая награда</span>', 'normal', '0', NULL, NULL, NULL),
(529, 0, 'Гудрон', NULL, 'craft', NULL, 'Вязкая жидкость или твердый асфальтоподобный продукт черного цвета. Когда начали массово возводить города , то покемоны земляных типов стали прорываться из недр земли, чтобы отведать сию &#34;сладость&#34;.', 10, 0, 'false', 'false', 'true', 'true', 'false', 'true', 0, NULL, '0', 0, 0, '', '', 0, '<span>Нечастая награда</span>', 'normal', '0', NULL, NULL, NULL),
(530, 0, 'Горький шоколад', NULL, 'craft', NULL, 'Обладает специфическим вкусом натуральных какао-бобов, масляно-горьким с длительным послевкусием и насыщенным ароматом. Но приходится не всем по вкусу.', 10, 0, 'false', 'false', 'true', 'true', 'false', 'true', 0, NULL, '0', 0, 0, '', '', 0, '<span>Нечастая награда</span>', 'normal', '0', NULL, NULL, NULL),
(531, 0, 'Хитин', NULL, 'craft', NULL, 'Представляет собой твёрдое бесцветное либо полупрозрачное вещество, не растворимое в воде. Поэтому хитин перемалывается в мелкую крошку и добавляется в блюда предназначенные для кормления жуков.', 10, 0, 'false', 'false', 'true', 'true', 'false', 'true', 0, NULL, '0', 0, 0, '', '', 0, '<span>Нечастая награда</span>', 'normal', '0', NULL, NULL, NULL),
(532, 0, 'Ветка с белого дерева', NULL, 'craft', NULL, 'Белое дерево находится под охранной, так как раньше массово использовалась в медицинском деле, из него варили сиропы и отвары. Поэтому в наше время многие коллекционеры бьются за право обладать хотя бы веточкой этого дерева.', 10, 0, 'false', 'false', 'true', 'true', 'false', 'true', 0, NULL, '0', 0, 0, '', '', 0, '<span>Нечастая награда</span>', 'normal', '0', NULL, NULL, NULL),
(533, 0, 'Древний кристалл насекомых', NULL, 'craft', NULL, 'Известный по многим легендам предмет, представляющий собой кристаллический осколок, ходят легенды , что он обладает могущественными, магическими свойствами.', 10, 0, 'false', 'false', 'true', 'true', 'false', 'true', 0, NULL, '0', 0, 0, '', '', 0, '<span>Нечастая награда</span>', 'normal', '0', NULL, NULL, NULL),
(534, 0, 'Древний кристалл тьмы', NULL, 'craft', NULL, 'Известный по многим легендам предмет, представляющий собой кристаллический осколок, ходят легенды , что он обладает могущественными, магическими свойствами.', 10, 0, 'false', 'false', 'true', 'true', 'false', 'true', 0, NULL, '0', 0, 0, '', '', 0, '<span>Нечастая награда</span>', 'normal', '0', NULL, NULL, NULL),
