INSERT INTO `base_location` (`id`, `name`, `description`, `region`, `pve`, `img_fight`, `event`, `tipe`, `search_tipe`, `weather`, `control`, `nalog`, `clan_reit`, `map_x`, `map_y`) VALUES
(0, 'Тюрьма', 'Тюрьма', 7, 0, 0, 0, 0, 'route', 0, '0,0', '0', 0, NULL, NULL),
(1, 'Дом', 'Дом — больше чем просто жилище. Это место, где время замедляет свой бег, где можно быть собой, где сердце находит покой, а душа — гармонию. Здесь каждая мелочь пропитана любовью и заботой, и именно поэтому сюда так хочется возвращаться снова и снова.', 7, 0, 0, 0, 0, 'city', 0, '0,0', '0', 0, 775, 1481),
(2, 'Поле для тренировок', 'Широкое поле для тренировок покемонов раскинулось под бескрайним небом, словно приглашая к новым свершениям. Его зелёная трава, мягкая и упругая, словно создана для того, чтобы на ней могли разминаться самые смелые тренеры, которые только начинают свой путь.', 7, 1, 1, 0, 0, 'route', 1, '0,0', '0', 0, 1143, 1479),
(3, 'Алабастия', 'Алабастия — это живописный уголок на юго-западе Канто, где природа и уют сливаются в гармонии. Этот небольшой городок, окружённый зелёными холмами и густым лесом, словно создан для спокойного отдыха. Солнечные дни здесь — обычное явление, наполняющее всё вокруг теплом и светом. Но главное сокровище Алабастии — это академия, где будущие тренеры покемонов делают первые шаги в своём увлекательном пути.', 7, 0, 1, 0, 1, 'city', 1, '0,0', '0', 0, 955, 1369),
(4, 'Лаборатория', 'Лаборатория словно живой организм, где каждый элемент выполняет свою важную функцию, где наука и технологии сливаются воедино, создавая пространство для великих открытий и смелых экспериментов. Это место, где рождаются новые идеи и воплощаются в жизнь самые амбициозные научные проекты.', 7, 0, 1, 0, 1, 'route', 0, '0,0', '0,0', 0, 1143, 1407),
(5, 'Дорога 1', 'Тропинка, словно приглашая в путешествие, ведёт вниз, открывая перед вами удивительный пейзаж. Она петляет между зелёными холмами, окружёнными густыми деревьями, и манит исследовать её дальше. По обе стороны от тропинки раскинулись куски скалы, покрытые яркой растительностью, а внизу извивается река, отражающая солнечные лучи. Вдали виднеются старинные здания с красными крышами, окружённые современными высотками, а над всем этим простирается чистое голубое небо с пушистыми облаками. Этот путь — начало приключения, где каждый шаг открывает новые горизонты красоты.', 7, 1, 0, 0, 0, 'route', 1, '0,0', '0', 0, 977, 1232),
(6, 'Веридиан', 'Величественный город раскинулся по обеим сторонам полноводной реки, чьи воды неторопливо несут свои серебристые потоки между древними берегами. Монументальный мост, словно  соединяет два мира, два берега, две части единого целого. Река неспешно несёт свои воды, а город живёт своей жизнью: по улицам снуют автомобили, в парках гуляют люди, в окнах домов горит тёплый свет. И кажется, что нет ничего прекраснее этого гармоничного союза природы и человеческого гения, воплощённого в камне, металле и стекле.', 7, 0, 0, 0, 0, 'city', 1, '0,0', '0', 0, 945, 1092),
(7, 'Дорога 22', 'Тропинка извивается между густыми зарослями зелени, уводя взгляд вдаль. Её поверхность мягко освещена солнечными лучами, пробивающимися сквозь кроны деревьев. По обе стороны от дороги раскинулись высокие травы и кустарники, создавая ощущение уюта и уединения.', 7, 1, 0, 0, 0, 'route', 1, '0,0', '0', 0, 769, 1232),
(8, 'Дорога 23', 'Этот маршрут пролегает через удивительную местность, где природа создала неповторимую симфонию из травянистых ковров и величественных валунов. Каждый шаг здесь открывает новые пейзажи, где изумрудная зелень гармонично переплетается с могучими камнями, словно застывшими стражами времени.', 7, 1, 0, 0, 0, 'route', 1, '0,0', '0', 0, 576, 1232),
(9, 'Загадочная тропа', 'Таинственный лесной маршрут окутан особой атмосферой волшебства и умиротворения. Здесь, в царстве вековых деревьев, мягкий свет солнца, словно сквозь вуаль, пробивается сквозь густую крону, создавая причудливую игру света и тени на земле.', 7, 1, 0, 0, 0, 'route', 1, '0,0', '0', 0, 294, 1232),
(10, 'Дорога 26', 'Извилистая тропинка протянулась между небольшими водоёмами, чьи берега укутаны в пышный изумрудный наряд из сочной травы, чуть припорошенной снегом. Примятая трава вдоль тропинки рассказывает истории о тех, кто проходил здесь до вас, оставляя едва заметные следы своего присутствия.', 7, 1, 0, 0, 0, 'route', 1, '0,0', '0', 0, 578, 1345),
(11, 'Дорога 27', 'По обе стороны дороги раскинулись изумрудные луга, украшенные белыми островками снежного покрова. Высокие ели, словно стражи, обрамляют путь, добавляя пейзажу величественности. На заднем плане возвышается величественная снежная гора, её белоснежные вершины сияют под лучами яркого солнца. Этот пейзаж наполнен ощущением спокойствия и гармонии, словно природа сама создала это место для отдыха души.', 7, 1, 0, 0, 0, 'route', 1, '0,0', '0', 0, 576, 1461),
(12, 'Дорога 28', 'Перед вами открывается живописный пейзаж, словно сошедший с полотна художника. Узкая тропинка, извиваясь между зелёных лугов, усыпанных снегом, ведёт вдаль. Живописное озеро раскинулось в стороне от дороги, его зеркальная гладь отражает лазурное небо и пушистые облака. Этот пейзаж словно приглашает вас остановиться и насладиться красотой природы, почувствовать гармонию и умиротворение, которые дарит этот удивительный уголок земли.', 7, 1, 0, 0, 0, 'route', 1, '0,0', '0', 0, 179, 1337),
(13, 'Снежная гора', 'Величественная локация, покрытая сверкающим слоем снега и льда. Здесь тренеры сталкиваются с холодными вызовами, включая мощных ледяных покемонов и коварные лавины. Уютные пещеры хранят тайны , приглашая смелых исследователей открыть их секреты в этом зимнем царстве!', 7, 1, 0, 0, 0, 'route', 4, '0,0', '0', 0, 129, 1475),
(14, 'Дорога 2', 'Тропинка через густой лес, окружённый высокими деревьями, ведёт к городу Пьютер. С одной стороны тропинки находится вход в хрустальную пещеру, украшенную сверкающими фиолетовыми кристаллами, которые переливаются на солнце. Вдали виднеется величественная гора, у подножия которой раскинулся город с серыми как камень домами. Картина передаёт ощущение спокойствия и магии, словно приглашая отправиться в это удивительное путешествие.', 7, 1, 0, 0, 0, 'route', 1, '0,0', '0', 0, 949, 926),
(15, 'Лес Веридиана', 'Узкая тропинка змеится сквозь сумрачный лес, где вековые деревья словно стражи древнего царства возносятся к небу. Их могучие стволы, покрытые мхом и лишайником, создают мрачный, но величественный коридор, по которому едва пробиваются лучи солнца, превращаясь в золотые нити, играющие между ветвей. Из-за тёмной и тенистой окружающей среды лес содержит большое количество различных покемонов.', 7, 1, 0, 0, 0, 'route', 1, '0,0', '0', 0, 724, 958),
(16, 'Пьютер', 'Величественный город, словно высеченный из цельной глыбы серого камня, примостился у подножия исполинской скалы. Серые каменные дома, будто древние стражи, возвышаются над узкими улочками, их стены хранят следы времени и историй многих поколений. Улицы вымощены булыжником, и каждый шаг здесь отзывается приглушённым эхом, отражающимся от каменных стен.', 7, 0, 0, 0, 0, 'city', 1, '0,0', '0', 0, 803, 810),
(17, 'Дорога 3', 'Узкая тропинка извивается между зелёными лугами, усыпанных яркими цветами, и ведёт к величественным горам. Лунная гора, возвышающаяся на фоне глубокого синего неба, освещена мягким светом полной луны, которая величественно плывёт среди пушистых облаков. Её скалистые склоны покрыты редкими деревьями и кустарниками, а вершины утопают в лёгкой дымке. Этот пейзаж излучает спокойствие и величие природы, словно приглашая остановиться и насладиться её красотой.', 7, 1, 0, 0, 0, 'route', 1, '0,0', '0', 0, 630, 826),
(18, 'Лунная гора', 'В небесах над загадочной горой словно открывается невидимый портал — именно здесь, в этом удивительном месте, метеориты особенно часто выбирают свой путь к земле. Эти космические камни, впитавшие в себя энергию звёзд и силу лунного света, становятся истинными драгоценностями горной сокровищницы. Недаром местные жители нарекли эту величественную вершину Лунной горой — ведь сама природа наделила её способностью превращать обычный космический мусор в лунные камни, хранящие тайны Вселенной. Легенда о Лунной горе живёт и по сей день, маня к себе искателей приключений и любителей чудес, готовых стать свидетелями этого космического чуда.', 7, 1, 0, 0, 0, 'route', 1, '0,0', '0', 0, 440, 782),
(19, 'Дорога 4', 'Живописный маршрут, словно шёлковая лента, вьётся сквозь густой лес, где с одной стороны величественно возвышается Лунная гора, чьи величественные очертания отражаются в зеркальной глади небольшого водоёма. Каждый шаг по этому маршруту наполнен особым очарованием, а сама природа словно приглашает путника остановиться, полной грудью вдохнуть свежий воздух и погрузиться в созерцание её первозданной красоты.', 7, 1, 0, 0, 0, 'route', 1, '0,0', '0', 0, 255, 850),
(20, 'Церулин', 'На живописном морском побережье раскинулся удивительный город, где гармонично переплелись эпохи: устремлённые ввысь современные небоскрёбы изящно соседствуют с величественными историческими зданиями, создавая неповторимый архитектурный ансамбль, а каждая достопримечательность этого приморского мегаполиса словно хранит свою особую историю, оставляя в душе путешественника неизгладимый след и вызывая желание возвращаться сюда снова и снова.', 7, 0, 0, 0, 0, 'city', 1, '0,0', '0', 0, 83, 683),
(21, 'Дорога 24', 'Дорога, вымощенная светлыми камнями, извивается вдоль берега, словно приглашая в путешествие по этому райскому уголку природы. Высокие деревья с густой листвой создают прохладную тень, а за ними простирается бескрайнее лазурное море, чьи волны мягко накатывают на песчаный берег. Небо, украшенное пушистыми облаками, заливает все вокруг мягким солнечным светом, создавая атмосферу тихого счастья.', 7, 1, 0, 0, 0, 'route', 1, '0,0', '0', 0, 73, 535),
(22, 'Дорога 25', 'Тропинка вьётся вдоль берега, утопая в мягкой зелени, которая играет оттенками от изумрудного до белоснежного. Могучие деревья с широкими кронами дарят прохладу, а за ними простирается безбрежное синее море, чьи волны ласково обнимают песчаный пляж.', 7, 1, 0, 0, 0, 'route', 1, '0,0', '0', 0, 99, 427),
(23, 'Морской берег', 'Живописное побережье, где лазурные волны нежно касаются золотистого песка. Локация изобилует яркими цветами и экзотическими растениями, создавая атмосферу тропического рая. Здесь можно встретить самых разнообразных покемонов – от игривых водных существ, играющих в прибой, до птиц, парящих над скалами в облаках. Этот уголок идеально подходит не только для захватывающих поединков, но и для волнующих поисков сокровищ, которые могут ожидать исследователей в скрытых глубинах моря.', 7, 1, 0, 0, 0, 'route', 1, '0,0', '0', 0, 183, 313),
(24, 'Мрачная пещера', 'Мрачная пещера – это таинственное и зловещее место. Здесь царит полумрак, и лишь редкие проблески света проникают сквозь трещины в стенах, освещая влажные камни. Воздух пропитан сыростью, а эхо шагов создает атмосферу безмолвия и загадки.', 7, 1, 0, 0, 0, 'route', 1, '0,0', '0', 0, 380, 567),
(25, 'Дорога 5', 'Дорога, словно золотая лента, извивается между зелёных холмов, усыпанных яркими цветами, и ведёт взгляд к величественному городу, раскинувшемуся у подножия гор. Высокие небоскрёбы, устремлённые в небо, отражаются в солнечных лучах, создавая ощущение гармонии между природой и урбанистикой. Голубое небо с пушистыми облаками добавляет картине лёгкости и мечтательности, а свежий ветер, кажется, шепчет о свободе и новых горизонтах.', 7, 1, 0, 0, 0, 'route', 1, '0,0', '0', 0, 720, 499),
(26, 'Шафран', 'Город в центральном Канто. Огромный мегаполис, сияющий разнообразными вывесками. Является крупнейшим и одним из самых оживлённых городов Канто, будучи известным даже в других регионах. Это не только центральный деловой район Канто, но и административный центр региона, включая вокзал, который позволяет легко путешествовать между Канто и Джото.', 7, 0, 0, 0, 0, 'city', 1, '0,0', '0', 0, 1041, 583),
(27, 'Вокзал Канто', 'Вокзал — место сильных и искренних эмоций: искренней радости при встрече, искренней горечи при расставании, предвкушения интересного и нового.', 7, 0, 0, 0, 0, 'route', 1, '0,0', '0', 0, 831, 627),
(28, 'Дорога 10', 'Извилистая зелёная тропа ведёт через скалистые утёсы к величественным вершинам. На горизонте виднеется закат, окрашивающий небо в тёплые оттенки оранжевого и розового, а солнце мягко освещает заснеженные пики. Атмосфера наполнена спокойствием и величием природы.', 7, 1, 0, 0, 0, 'route', 1, '0,0', '0', 0, 532, 383),
(29, 'Площадка электростанции', 'Солнечный свет заливает площадку перед электростанцией, создавая контраст между разрушенным зданием и живой природой. Здание выглядит массивным и внушительным, с высокими башнями и трубами, покрытыми ржавчиной и облупившейся краской.', 7, 1, 0, 0, 0, 'route', 1, '0,0', '0', 0, 532, 287),
(30, 'Электростанция', 'Заброшенная электростанция навевает тревогу. Здесь довольно тихо, пустынные корпуса завалены сломанной мебелью, мусором, обрывками документов, канистрами, трубами, в цехах ржавеет оборудование и техника.', 7, 1, 0, 0, 0, 'route', 1, '0,0', '0', 0, 536, 206),
(31, 'Вермилион', 'Вермилион — величественный город, гордо возвышающийся среди живописных просторов региона Канто. Его улицы представляют собой настоящую симфонию городской жизни, где каждый уголок дышит уютом и комфортом.  Здесь, среди современных зданий и исторических построек, расположились многочисленные кафе, каждое из которых словно соревнуется с другим в изяществе оформления. Пышные цветочные композиции украшают веранды и окна заведений, создавая неповторимую атмосферу цветущего сада посреди мегаполиса.', 7, 0, 0, 0, 0, 'city', 1, '0,0', '0', 0, 1344, 751),
(32, 'Дорога 8', 'Тропа, залитая золотистыми лучами солнца, словно драгоценная нить, вьётся между величественных деревьев. С обеих сторон её нежно обрамляют фиолетовые цветы, создающие на земле роскошный живой ковёр, который переливается всеми оттенками сиреневого. Впереди, маня и завораживая, расстилается горизонт, где небесная лазурь плавно сливается с изумрудным покровом леса. Это волшебное место наполняет душу особым восторгом и умиротворением, которого так не хватает в наши дни.', 7, 1, 0, 0, 0, 'route', 1, '0,0', '0', 0, 965, 471),
(33, 'Дорога 6', 'Тропинка, выложенная старинными булыжниками, соединяет два золотых пшеничных поля, уходя вдаль под сенью величественных дубов. Их раскидистые кроны, играя в солнечных лучах, дарят живительную прохладу в жаркий день, словно приглашая в путешествие по этому сказочному пейзажу.', 7, 1, 0, 0, 0, 'route', 1, '0,0', '0', 0, 1187, 689),
(34, 'Хрустальная пещера', 'Загадочное подземелье, где сверкающие кристаллы освещают тьму ярким фиолетовым сиянием. Здесь живая экосистема из редких покемонов и красивейших минералов создаёт уникальные условия для исследователей.', 7, 1, 0, 0, 0, 'route', 1, '0,0', '0', 0, 1117, 882),
(35, 'Дорога 16', 'Путь, протянувшийся вдоль изумрудных лесов и ярких цветущих полей, словно приглашает в путешествие по этому живописному уголку природы. Широкая тропа, усеянная камнями и маленькими водоемами, ведет к уютным деревянным домикам, окруженным буйством зелени и цветов. Вдали возвышаются величественные горы, а небо, украшенное пушистыми облаками, завершает эту идиллическую картину.', 7, 1, 0, 0, 0, 'route', 1, '0,0', '0', 0, 1458, 970),
(36, 'Дом механика', 'Мастерская механика — это уютное пространство, наполненное инструментами, деталями и механизмами. На стеллажах аккуратно разложены инструменты, а на столе лежат разобранные предметы, ожидающие починки. Атмосфера мастерской пропитана духом творчества и трудолюбия, где каждая деталь имеет своё место, а каждая починка — это маленькое чудо.', 7, 0, 0, 0, 0, 'route', 1, '0,0', '0', 0, 1438, 1204),
(37, 'Дорога 18', 'Широкая дорога неспешно вьётся по бескрайней равнине, утопающей в изумрудной высокой траве, которая колышется под ласковым ветерком, создавая завораживающий живой ковёр. По обе стороны пути колышутся нежные стебли, отливающие всеми оттенками зелёного в лучах солнца, а кое-где виднеются яркие пятна полевых цветов, словно разбросанные по земле драгоценные камни.', 7, 1, 0, 0, 0, 'route', 1, '0,0', '0', 0, 1684, 866),
(38, 'Фуксия', 'В самом сердце города раскинулось великолепное озеро, чьи кристально чистые воды отражают лазурное небо и пышные кроны экзотических деревьев, растущих по его берегам. Архитектурный облик города поражает разнообразием: здесь гармонично соседствуют старинные особняки с резными балконами, современные небоскрёбы с зелёными террасами и причудливые домики, увитые цветущими лианами. Вдоль улиц раскинулись сады с редкими растениями, источающими сладкий аромат, а в воздухе витает особая атмосфера умиротворения и волшебства, притягивающая путешественников со всего света.', 7, 0, 0, 0, 0, 'city', 1, '0,0', '0', 0, 1811, 553),
(39, 'Лавандия', 'Маленький городок окутан таинственной дымкой пурпурного тумана, который словно вуалью покрывает его узкие улочки и старинные здания. В центре города возвышается величественная Башня покемонов, украшенная сотнями надгробий, где покоятся души умерших покемонов. Ветви старых деревьев отбрасывают причудливые тени на мощёные дорожки, а в воздухе витает едва уловимый запах увядающих цветов. Редкие прохожие спешат по своим делам, стараясь не задерживаться на пустынных улицах, где время будто остановилось, храня память о тех, кто уже никогда не вернётся.', 7, 0, 0, 0, 0, 'city', 1, '0,0', '0', 0, 847, 315),
(40, 'Дорога 9', 'Предгорный путь, извиваясь, ведёт через живописный ландшафт, где валуны, словно стражи, обрамляют тропинку. Камни, покрытые мхом и травой, придают пейзажу суровую красоту. Тропинка, вытоптанная временем, петляет между ними, уводя взгляд вдаль, к величественным горам.', 7, 1, 0, 0, 0, 'route', 1, '0,0', '0', 0, 270, 409),
(41, 'Дорога 17', 'Эта тропинка словно приглашает в мир, где время замирает. Высокие деревья, словно стражи, обрамляют путь, их кроны смыкаются над головой, создавая зелёный свод. Лучи солнца пробиваются сквозь листву, рисуя на земле золотистые узоры. Воздух наполнен ароматом свежести, а тишина леса кажется живой.', 7, 1, 0, 0, 0, 'route', 1, '0,0', '0', 0, 1488, 1108),
(42, 'Дорога 19', 'Эта дорога, устланная мягким грунтом и окруженная густыми деревьями, предлагает тренерам насладиться природой и разнообразием покемонов. По обе стороны пути растут нежные цветы и кустарники, привлекающие различных покемонов.', 7, 1, 0, 0, 0, 'route', 1, '0,0', '0', 0, 1881, 814),
(43, 'Дорога 20', 'Дорога, ведущая к открытому морю, начинается с узкой тропинки, которая постепенно расширяется, превращаясь в широкую мощёную аллею. По обе стороны растут высокие деревья, их ветви слегка покачиваются на ветру, создавая ощущение движения. Вдали, за горизонтом, раскинулся остров Сикеттон. Его очертания едва различимы, но он словно парит над водой, создавая ощущение загадочности и романтики.', 7, 1, 0, 0, 0, 'route', 1, '0,0', '0', 0, 1885, 996),
(44, 'Остров Сикеттон', 'Уединённый и загадочный уголок региона Канто. Остров покрыт густыми лесами, где высокие деревья сплетаются кронами, а узкие тропинки петляют среди мха и корней. В воздухе витает свежий аромат хвои и солёного бриза.', 7, 1, 0, 0, 0, 'route', 1, '0,0', '0', 0, 1969, 1329),
(45, 'Аллея папоротников', 'Узкая извилистая тропинка петляет между величественных папоротников, чьи пышные зелёные листья создают причудливую игру света и тени на земле. По краям тропинки рассыпаны нежные белые цветы, которые выглядывают из густой зелени травы, создавая яркие акценты на фоне изумрудной листвы. Каждый шаг по этой тропинке открывает новые детали лесного пейзажа, приглашая путешественника погрузиться в мир природы и забыть о суете повседневности.', 7, 1, 0, 0, 0, 'route', 1, '0,0', '0', 0, 1722, 373),
(46, 'Солнечная поляна', 'Уютная лесная поляна залита тёплым солнечным светом, который мягко пробивается сквозь густую крону высоких деревьев, создавая на земле причудливый узор из золотистых бликов и тенистых пятен; изумрудная трава ковром покрывает землю, а в воздухе словно разлито ощущение покоя и безмятежности; лёгкий ветерок колышет листья, и солнечные лучи, играя в прятки с листвой, рисуют на траве мерцающие узоры, наполняя пространство волшебством и умиротворением', 7, 1, 0, 0, 0, 'route', 1, '0,0', '0', 0, 1698, 273),
(47, 'Желтый луг', 'Яркая и красочная локация, охваченная цветущими полями желтых цветов и густой зеленью. Солнечный свет ласково освещает луг, создавая теплую и приветливую атмосферу для тренеров и покемонов. ', 7, 1, 0, 0, 0, 'route', 1, '0,0', '0', 0, 1782, 100),
(48, 'Янтарное озеро', 'Янтарное озеро — словно драгоценный камень, отражающий в своих водах золотистые кроны окружающих деревьев; его поверхность мерцает в лучах солнца, создавая волшебное зрелище, где реальность сливается с мечтой; пологий берег усыпан сверкающими кусочками янтаря, которые блестят на солнце, словно россыпь драгоценных камней, а между ними зеленеют яркие растения, добавляя картине сочности и жизни; воздух наполнен спокойствием и умиротворением, а лёгкий ветерок создаёт на воде едва заметные волны, играющие с солнечными бликами.', 7, 1, 0, 0, 0, 'route', 1, '0,0', '0', 0, 1279, 98),
(49, 'Покецентр', 'В уютном кабинете сестры Джой царит атмосфера спокойствия и заботы. Здесь каждый пациент может довериться её профессионализму и чуткости. Её верная помощница Ченси всегда рядом, готовая поддержать в любой момент.', 7, 0, 0, 0, 0, 'city', 0, '0,0', '0', 0, NULL, NULL),
(50, 'Академия', 'В просторном зале академии для тренеров покемонов, залитом мягким светом, две ученицы в школьной форме сидят на диванах, каждая со своим покемоном. Комната наполнена уютом: большие окна открывают вид на зелёный пейзаж, а растения в горшках и деревянные столы создают атмосферу спокойствия. Девушки выглядят сосредоточенными, готовыми к новым приключениям и испытаниям, которые ждут их впереди.', 7, 0, 0, 0, 0, 'city', 0, '0,0', '0', 0, 945, 1487),
(51, 'Лесной оазис', 'Густой и влажный лесной рай с небольшой речушкой, где можно передохнуть и перевести дух. Дикие покемоны тоже оценили этот оазис жизни и живут друг с другом без конфликтов.', 7, 1, 0, 0, 0, 'route', 1, '0,0', '0', 0, 528, 1080),
(52, 'Колючая тропа', 'Дикая и опасная локация, переполненная острыми шипами и запутанными зарослями. Путь проходит сквозь густые заросли, где каждый шаг может привести к встрече с местными покемонами . Осторожность – ваше главное оружие, ведь на этой тропе притаились как сильные противники, так и редкие экземпляры, ожидающие смелых исследователей, готовых преодолеть все преграды!', 7, 1, 0, 0, 0, 'route', 1, '0,0', '0', 0, 382, 994),
(53, 'Зеленый пруд', 'Идиллическое место, утопающее в зелени. Это спокойный водоем с кристально чистой водой и плавающими лилиями, окруженный тенистыми деревьями. Здесь обитают множество  покемонов, которые наслаждаются умиротворением природы. Это место создает атмосферу, наполненную покоем и гармонией, что делает Зеленый пруд прекрасным уголком для приключений и дружеских встреч!', 7, 1, 0, 0, 0, 'route', 1, '0,0', '0', 0, 159, 1042),
(54, 'Казино', 'Казино — это место, где роскошь и азарт переплетаются в танце света и звуков. Высокие потолки, украшенные хрустальными люстрами, словно звезды, освещают зал, наполняя его мягким сиянием. Игровые автоматы, сверкающие яркими экранами, манят своей загадочностью, обещая удачу каждому, кто осмелится сделать ставку.', 7, 0, 0, 0, 1, 'route', 0, '0,0', '0,0', 0, 1157, 469),
(55, 'Локация для Канто1', '', 7, 0, 0, 0, 0, 'city', 0, '0,0', '0', 0, NULL, NULL),
