INSERT INTO `base_quest` (`id`, `name`, `about`, `data`, `region`, `exp`, `location`, `lvl`, `time`, `class_lvl`, `ready`) VALUES
(1, 'Начало путешествия', 'Сегодня — первый день твоего пути тренера. Утро дома, Академия, поиск профессора и первый важный выбор. В пути ты поможешь профессору, выберешь стартового покемона и впервые вступишь в бой — как в классическом сюжете Канто.', '', 7, '500', 'Канто -> Дом', 'C', '30 минут', 'easy_lvl', 1),
(2, 'Мастер эволюции', NULL, '', 7, '500', 'Калос → Тропа 1', 'C', '1 час', 'easy_lvl', 0),
(3, 'Мастер боев', NULL, '', 1, '500', 'Калос → Тропа 5', 'C', '30 минут', 'easy_lvl', 0),
