(18, 'Усиления Дорана', NULL, '', 3, '900', 'Хоенн → Лаваридж Таун', 'B', '5 часов', 'medium_lvl', 0),
(19, 'Помощь в мастерской', NULL, '', 3, '900', 'Джотто → Мастерская', 'B', '5 часов', 'medium_lvl', 0),
