(31, 'Багровый гербарий', NULL, '', 0, '800', 'Джотто → Черигроу', 'B', '5 часов', 'medium_lvl', 0),
(32, 'Сезон дождей', NULL, '', 0, '500', 'Хоенн → Пассифидлог Таун', 'C', '2 часа', 'easy_lvl', 0),
(33, 'Закрытый пляж', NULL, '', 0, '1.000', 'Калос → Пляж', 'B', '8 часов', 'medium_lvl', 0),
(34, 'Мороженщик', NULL, '', 0, '600', 'Калос → Тропа 19', 'C', '3 часа', 'easy_lvl', 0),
(35, 'Голубая роза', NULL, '', 0, '1.800', 'Калос → Ледяная гора', 'A', '1 день', 'hard_lvl', 0),
(36, 'На абордаж!', NULL, '', 0, '1.000', 'Хоенн → Муссдип', 'B', '6 часов', 'medium_lvl', 0),
(37, 'Ночные прятки', NULL, '', 0, '350', 'Джотто → Темная пещера', 'C', '1 час', 'easy_lvl', 0),
(38, 'Темный принц', NULL, '', 0, '1.600', 'Джотто → Алтарь', 'A', '15 часов', 'hard_lvl', 0),
(39, 'Падение метеорита', NULL, '', 0, '800', 'Хоенн → Водопад', 'B', '3 часа', 'medium_lvl', 0),
(40, 'Полнолуние', NULL, '', 0, '500', 'Джотто → Циавуд', 'C', '2 часа', 'easy_lvl', 0),
(41, 'Важная вещь', NULL, '', 0, '600', 'Калос → Порт Санталуна', 'C', '2 часа', 'easy_lvl', 0),
(42, 'Потерянная кукла', NULL, '', 0, '1500', 'Калос → Тропа 1', 'A', 'день', 'hard_lvl', 0),
(50, 'Богатый Ричи', NULL, '', 0, '200', 'Канто', '1', '300', 'easy_lvl', 0),
(51, 'Путь к Снежной горе', 'На дороге к Снежной горе путь перекрывает огромный покемон. Кажется, причина его агрессии совсем не в вас. Разобравшись в ситуации и получив подсказку в покецентре, вы найдёте способ пройти дальше и помочь тем, кто в этом действительно нуждается. За проявленные заботу и смекалку вас ждёт достойная награда.', '', 7, '500', 'Канто -> Дорога 28', 'С', '2 часа', 'easy_lvl', 1),
(120, 'Эхо полуночного поезда', 'Ночные помехи на линии Канто–Джотто. Соберите эхо-символы в поезде, соберите камертон у техника и синхронизируйте часы на станции.', '{\r\n    \"steps\":[\r\n      {\"step\":1,\"title\":\"Ночной рейс Канто→Джотто\",\"hint\":\"Соберите 3 эхо-символа в поезде (лок. 8010).\"},\r\n      {\"step\":2,\"title\":\"Техник в Джотто\",\"hint\":\"Соберите камертон из символов или оплатите 10000 генкаров.\"},\r\n      {\"step\":3,\"title\":\"Синхронизация часов\",\"hint\":\"Вернитесь в Канто и дождитесь точного отправления.\"},\r\n      {\"step\":4,\"title\":\"Призрачный проводник\",\"hint\":\"Победите проводника и получите награды.\"}\r\n    ],\r\n    \"train\":{\"from\":27,\"to\":70,\"train_loc\":8010},\r\n    \"rewards\":{\"money\":50000,\"items\":[604,605]}\r\n  }', 0, '2000', 'Канто ↔ Джотто', 'C', '30 минут', 'easy_lvl', 1),
(121, 'Ключи Шторма', 'Собери четыре “ключа” из живых сигнатур (Ветер, Ток, Лоза, Прилив), сдай снабжение и пройди испытание \"Жаворонка\".', '', 7, '500', 'Канто', '', '', '', 1),
(130, 'Инкубатор трёх стихий', 'Питомнику нужна помощь: выбери стихию яйца (Огонь/Вода/Трава), принеси технику материалы для калибровки и вернись за запуском инкубатора. Награда: генкары, расходники и покемон по выбранной стихии.', '', 7, '900', 'Канто → Питомник', 'B', '4 часа', 'medium_lvl', 1),
(131, 'Удочка мастера', 'На пристани Янтарного озера требуется помощь: нужно пройти испытание у воды и заслужить удочку.', '', 7, '700', 'Канто → Янтарное озеро', 'B', '30 минут', 'normal_lvl', 1),
(132, 'Проверка стажёра Покемаркета', 'Новый продавец Марек нервничает перед проверкой. Помоги ему наладить сканер цен, оформить тестовый выкуп и справиться с подозрительным покупателем.', '{\"steps\":[\r\n    {\"id\":1,\"title\":\"Сканер цен\",\"detail\":\"Принести 1 деталь для замены (осколок громового/водного/лиственного камня) или оплатить замену платы.\"},\r\n    {\"id\":2,\"title\":\"Тестовый выкуп\",\"detail\":\"Отдать 5 покеболов для проверки процедуры возврата.\"},\r\n    {\"id\":3,\"title\":\"Ситуация у витрины\",\"detail\":\"Разобраться с подозрительным покупателем (вариант с боем или без).\"}\r\n ],\"type\":\"linear\",\"no_rewards_in_ui\":true}', 7, '600', 'Канто -> Веридиан', 'C', '15 минут', 'easy_lvl', 1),
(1101, 'Дорога 1: первый улов', 'Поймай своего первого дикого покемона. Это закрепит навыки боя и использования покеболов.', '', 7, '400', 'Канто -> Дорога 1', 'C', '20 минут', 'easy_lvl', 1),
(1102, 'Покецентр: первая помощь', 'Зайди в Покецентр и вылечи команду у сестры Джой. Тренер должен заботиться о покемонах.', '', 7, '300', 'Канто -> Покецентр', 'C', '10 минут', 'easy_lvl', 1),
(1103, 'Офицер Дженни: подозрительные воры', 'Помоги офицеру Дженни остановить подозрительных людей, которые пугают прохожих и пытаются похищать покемонов.', '', 7, '600', 'Канто -> Город', 'B', '25 минут', 'mid_lvl', 1),
(1104, 'Первый стадион: испытание лидера', 'Брось вызов лидеру первого стадиона. Победа докажет, что ты готов двигаться дальше.', '', 7, '900', 'Канто -> Стадион', 'B', '30 минут', 'mid_lvl', 1),
(1105, 'Развилка: выбор пути', 'После стадиона выбери маршрут: рискованный (быстрее и сложнее) или безопасный (спокойнее и проще). Выбор сохранится и будет влиять на дальнейшие задания.', '', 7, '200', 'Канто -> Развилка', 'B', '5 минут', 'mid_lvl', 1);
