INSERT INTO `base_work` (`id`, `name`, `info`, `pokemon_work`, `salary`, `places`) VALUES
(1, 'Врач', 'Не верите, что клятву Гиппократа дают и покемоны? Так вот, даже они способны стать профессиональными врачами и помогать больным. Иногда, благодаря их магической силе, они становятся в деле гораздо более полезными, чем люди.', '<div class=\"pokSELECT\" onclick=\"openDex(40)\"><img src=\"/img/pokemons/animation/040.png\">#040 Виглипафф</div> <div class=\"pokSELECT\" onclick=\"openDex(176)\"><img src=\"/img/pokemons/animation/176.png\">#176 Тогетик</div><div class=\"pokSELECT\" onclick=\"openDex(184)\"><img src=\"/img/pokemons/animation/184.png\">#184 Азумарил</div><div class=\"pokSELECT\" onclick=\"openDex(242)\"><img src=\"/img/pokemons/animation/242.png\">#242 Блисси</div><div class=\"pokSELECT\" onclick=\"openDex(358)\"><img src=\"/img/pokemons/animation/358.png\">#358 Чимечо</div><div class=\"pokSELECT\" onclick=\"openDex(531)\"><img src=\"/img/pokemons/animation/531.png\">#531 Аудино</div><div class=\"pokSELECT\" onclick=\"openDex(576)\"><img src=\"/img/pokemons/animation/576.png\">#576 Готителла</div><div class=\"pokSELECT\" onclick=\"openDex(620)\"><img src=\"/img/pokemons/animation/620.png\">#620 Миншао</div> <div class=\"pokSELECT\" onclick=\"openDex(683)\"><img src=\"/img/pokemons/animation/683.png\">#683 Ароматизз</div><div class=\"pokSELECT\" onclick=\"openDex(764)\"><img src=\"/img/pokemons/animation/764.png\">#764 Комфи</div>', 20000, 20),
(2, 'Полицейский', 'Мир опасен, поэтому на защиту мирным покемонам и людям выходят офицеры Дженни и ее помощники. На эту должность подходят доблестные покемоны, которые верны своему делу и являются очень ответственными.', '<div class=\"pokSELECT\" onclick=\"openDex(59)\"><img src=\"/img/pokemons/animation/059.png\">#059 Арканайн</div> <div class=\"pokSELECT\" onclick=\"openDex(405)\"><img src=\"/img/pokemons/animation/405.png\">#405 Люксрей</div><div class=\"pokSELECT\" onclick=\"openDex(508)\"><img src=\"/img/pokemons/animation/508.png\">#508 Стотланд</div><div class=\"pokSELECT\" onclick=\"openDex(628)\"><img src=\"/img/pokemons/animation/628.png\">#628 Брейвиари</div><div class=\"pokSELECT\" onclick=\"openDex(660)\"><img src=\"/img/pokemons/animation/660.png\">#660 Диггерзбай</div><div class=\"pokSELECT\" onclick=\"openDex(673)\"><img src=\"/img/pokemons/animation/673.png\">#673 Гогоат</div><div class=\"pokSELECT\" onclick=\"openDex(735)\"><img src=\"/img/pokemons/animation/735.png\">#735 Гамшус</div><div class=\"pokSELECT\" onclick=\"openDex(773)\"><img src=\"/img/pokemons/animation/773.png\">#773 Силвалли</div>', 20000, 0),
(3, 'Почтальон', 'Почта покемонов существует с давних времен и пользуется популярностью среди всех людей. Доставить вовремя посылку важно и эту работу делают быстрые летающие покемоны. Только они могут тащить на себе грузы и делать это лучше всех.', '<div class=\"pokSELECT\" onclick=\"openDex(6)\"><img src=\"/img/pokemons/animation/006.png\">#006 Чаризард</div> <div class=\"pokSELECT\" onclick=\"openDex(18)\"><img src=\"/img/pokemons/animation/018.png\">#018 Пиджеот</div><div class=\"pokSELECT\" onclick=\"openDex(22)\"><img src=\"/img/pokemons/animation/022.png\">#022 Фироу</div><div class=\"pokSELECT\" onclick=\"openDex(149)\"><img src=\"/img/pokemons/animation/149.png\">#149 Драгонайт</div><div class=\"pokSELECT\" onclick=\"openDex(227)\"><img src=\"/img/pokemons/animation/227.png\">#227 Скармори</div><div class=\"pokSELECT\" onclick=\"openDex(277)\"><img src=\"/img/pokemons/animation/277.png\">#277 Свилоу</div><div class=\"pokSELECT\" onclick=\"openDex(334)\"><img src=\"/img/pokemons/animation/334.png\">#334 Алтария</div><div class=\"pokSELECT\" onclick=\"openDex(398)\"><img src=\"/img/pokemons/animation/398.png\">#398 Стараптор</div> <div class=\"pokSELECT\" onclick=\"openDex(521)\"><img src=\"/img/pokemons/animation/521.png\">#521 Унвезант</div><div class=\"pokSELECT\" onclick=\"openDex(663)\"><img src=\"/img/pokemons/animation/663.png\">#663 Талонфлейм</div>', 15000, 0),
(4, 'Спортсмен', 'Соревнования между регионами будут актуальны всегда, каждый стремится выставить своих сильных покемонов как самых лучших. В спорте важна сила, ловкость, скорость, выносливость и много других качеств - для всего этого есть бойцовские и не только покемоны.', '<div class=\"pokSELECT\" onclick=\"openDex(106)\"><img src=\"/img/pokemons/animation/106.png\">#106 Хитмонли</div> <div class=\"pokSELECT\" onclick=\"openDex(107)\"><img src=\"/img/pokemons/animation/107.png\">#107 Хитмончан</div><div class=\"pokSELECT\" onclick=\"openDex(237)\"><img src=\"/img/pokemons/animation/237.png\">#237 Хитмонтоп</div><div class=\"pokSELECT\" onclick=\"openDex(297)\"><img src=\"/img/pokemons/animation/297.png\">#297 Харияма</div><div class=\"pokSELECT\" onclick=\"openDex(448)\"><img src=\"/img/pokemons/animation/448.png\">#448 Лукарио</div><div class=\"pokSELECT\" onclick=\"openDex(538)\"><img src=\"/img/pokemons/animation/538.png\">#538 Тро</div><div class=\"pokSELECT\" onclick=\"openDex(539)\"><img src=\"/img/pokemons/animation/539.png\">#539 Соук</div><div class=\"pokSELECT\" onclick=\"openDex(675)\"><img src=\"/img/pokemons/animation/675.png\">#675 Пангоро</div> <div class=\"pokSELECT\" onclick=\"openDex(701)\"><img src=\"/img/pokemons/animation/701.png\">#701 Холуча</div><div class=\"pokSELECT\" onclick=\"openDex(768)\"><img src=\"/img/pokemons/animation/768.png\">#768 Голисопод</div>', 20000, 0),
(5, 'Строитель', 'Строитель - профессия опасная и тяжелая, поэтому туда могут быть отправлены только покемоны с высоким показателем силы,. Только они способны возводить здания или класть дороги.', '<div class=\"pokSELECT\" onclick=\"openDex(57)\"><img src=\"/img/pokemons/animation/057.png\">#057 Праймап</div> <div class=\"pokSELECT\" onclick=\"openDex(62)\"><img src=\"/img/pokemons/animation/062.png\">#062 Поливтор</div><div class=\"pokSELECT\" onclick=\"openDex(68)\"><img src=\"/img/pokemons/animation/068.png\">#068 Мачамп</div><div class=\"pokSELECT\" onclick=\"openDex(105)\"><img src=\"/img/pokemons/animation/105.png\">#105 Маровак</div><div class=\"pokSELECT\" onclick=\"openDex(115)\"><img src=\"/img/pokemons/animation/115.png\">#115 Кангасхан</div><div class=\"pokSELECT\" onclick=\"openDex(217)\"><img src=\"/img/pokemons/animation/217.png\">#217 Урсаринг</div><div class=\"pokSELECT\" onclick=\"openDex(534)\"><img src=\"/img/pokemons/animation/534.png\">#534 Конкелдур</div><div class=\"pokSELECT\" onclick=\"openDex(614)\"><img src=\"/img/pokemons/animation/614.png\">#614 Биартик</div><div class=\"pokSELECT\" onclick=\"openDex(689)\"><img src=\"/img/pokemons/animation/689.png\">#689 Барбаракл</div> <div class=\"pokSELECT\" onclick=\"openDex(760)\"><img src=\"/img/pokemons/animation/760.png\">#760 Бьюэр</div>', 25000, 0),
(6, 'Флорист', 'Любовь к флоре и стремление сделать окружающий мир прекраснее родили такую профессию. Обычно мастерами этого дела становятся травяные покемоны или покемоны-жуки. Однако, даже им нужно учиться, чтобы достичь в этом деле мастерства.', '<div class=\"pokSELECT\" onclick=\"openDex(154)\"><img src=\"/img/pokemons/animation/154.png\">#154 Меганиум</div> <div class=\"pokSELECT\" onclick=\"openDex(189)\"><img src=\"/img/pokemons/animation/189.png\">#189 Джумплафф</div><div class=\"pokSELECT\" onclick=\"openDex(315)\"><img src=\"/img/pokemons/animation/315.png\">#315 Розелия</div><div class=\"pokSELECT\" onclick=\"openDex(416)\"><img src=\"/img/pokemons/animation/416.png\">#416 Веспиквин</div><div class=\"pokSELECT\" onclick=\"openDex(542)\"><img src=\"/img/pokemons/animation/542.png\">#542 Ливанни</div><div class=\"pokSELECT\" onclick=\"openDex(549)\"><img src=\"/img/pokemons/animation/549.png\">#549 Лилигант</div><div class=\"pokSELECT\" onclick=\"openDex(709)\"><img src=\"/img/pokemons/animation/709.png\">#709 Тривенант</div><div class=\"pokSELECT\" onclick=\"openDex(711)\"><img src=\"/img/pokemons/animation/711.png\">#711 Гургейст</div> <div class=\"pokSELECT\" onclick=\"openDex(754)\"><img src=\"/img/pokemons/animation/754.png\">#754 Люрантис</div><div class=\"pokSELECT\" onclick=\"openDex(763)\"><img src=\"/img/pokemons/animation/763.png\">#763 Тсарина</div>', 15000, 0),
(7, 'Циркач', 'Никто не забыл и о развлечениях - цирк всегда к вашим услугам! Забавные покемоны с талантом выступать на сцене не оставят вас равнодушными и вы уйдете с выступления с хорошим настроением.', '<div class=\"pokSELECT\" onclick=\"openDex(122)\"><img src=\"/img/pokemons/animation/122.png\">#122 Мистер Майм</div> <div class=\"pokSELECT\" onclick=\"openDex(124)\"><img src=\"/img/pokemons/animation/124.png\">#124 Джинкс</div><div class=\"pokSELECT\" onclick=\"openDex(301)\"><img src=\"/img/pokemons/animation/301.png\">#301 Делкетти</div><div class=\"pokSELECT\" onclick=\"openDex(354)\"><img src=\"/img/pokemons/animation/354.png\">#354 Банит</div><div class=\"pokSELECT\" onclick=\"openDex(424)\"><img src=\"/img/pokemons/animation/424.png\">#424 Эмбипом</div><div class=\"pokSELECT\" onclick=\"openDex(512)\"><img src=\"/img/pokemons/animation/512.png\">#512 Симисейдж</div><div class=\"pokSELECT\" onclick=\"openDex(514)\"><img src=\"/img/pokemons/animation/514.png\">#514 Симисир</div><div class=\"pokSELECT\" onclick=\"openDex(516)\"><img src=\"/img/pokemons/animation/516.png\">#516 Симипур</div><div class=\"pokSELECT\" onclick=\"openDex(730)\"><img src=\"/img/pokemons/animation/730.png\">#730 Примарина</div> <div class=\"pokSELECT\" onclick=\"openDex(741)\"><img src=\"/img/pokemons/animation/741.png\">#741 Орикорио</div>', 15000, 0),
(8, 'Пожарник', 'Работники этой профессии постоянно подвергают жизнь опасности, работая в огне. На такую работу обычно берут покемонов, способных противостоять огню.', '<div class=\"pokSELECT\" onclick=\"openDex(131)\"><img src=\"/img/pokemons/animation/131.png\">#131 Лапрас</div> <div class=\"pokSELECT\" onclick=\"openDex(134)\"><img src=\"/img/pokemons/animation/134.png\">#134 Вапореон</div><div class=\"pokSELECT\" onclick=\"openDex(195)\"><img src=\"/img/pokemons/animation/195.png\">#195 Квагсаер</div><div class=\"pokSELECT\" onclick=\"openDex(350)\"><img src=\"/img/pokemons/animation/350.png\">#350 Милотик</div><div class=\"pokSELECT\" onclick=\"openDex(395)\"><img src=\"/img/pokemons/animation/395.png\">#395 Эмполеон</div><div class=\"pokSELECT\" onclick=\"openDex(565)\"><img src=\"/img/pokemons/animation/565.png\">#565 Карракоста</div><div class=\"pokSELECT\" onclick=\"openDex(581)\"><img src=\"/img/pokemons/animation/581.png\">#581 Сванна</div><div class=\"pokSELECT\" onclick=\"openDex(593)\"><img src=\"/img/pokemons/animation/593.png\">#593 Джеллисент</div><div class=\"pokSELECT\" onclick=\"openDex(689)\"><img src=\"/img/pokemons/animation/689.png\">#689 Барбаракл</div> <div class=\"pokSELECT\" onclick=\"openDex(693)\"><img src=\"/img/pokemons/animation/693.png\">#693 Кловицер</div>', 25000, 0),
(9, 'Электрик', 'Работа с электричеством опасна и сложна. Таким делом занимаются покемоны, обладающие силой создавать и проводить ток. Им не составит труда устранить неполадку.', '<div class=\"pokSELECT\" onclick=\"openDex(26)\"><img src=\"/img/pokemons/animation/026.png\">#026 Райчу</div> <div class=\"pokSELECT\" onclick=\"openDex(101)\"><img src=\"/img/pokemons/animation/101.png\">#101 Электрод</div><div class=\"pokSELECT\" onclick=\"openDex(125)\"><img src=\"/img/pokemons/animation/125.png\">#125 Электробазз</div><div class=\"pokSELECT\" onclick=\"openDex(135)\"><img src=\"/img/pokemons/animation/135.png\">#135 Джолтеон</div><div class=\"pokSELECT\" onclick=\"openDex(310)\"><img src=\"/img/pokemons/animation/310.png\">#310 Манектрик</div><div class=\"pokSELECT\" onclick=\"openDex(405)\"><img src=\"/img/pokemons/animation/405.png\">#405 Люксрей</div><div class=\"pokSELECT\" onclick=\"openDex(462)\"><img src=\"/img/pokemons/animation/462.png\">#462 Магнезон</div><div class=\"pokSELECT\" onclick=\"openDex(596)\"><img src=\"/img/pokemons/animation/596.png\">#596 Гальвантула</div><div class=\"pokSELECT\" onclick=\"openDex(604)\"><img src=\"/img/pokemons/animation/604.png\">#604 Илектросс</div> <div class=\"pokSELECT\" onclick=\"openDex(695)\"><img src=\"/img/pokemons/animation/695.png\">#695 Гелиолиск</div>    ', 15000, 0),
(10, 'Спасатель', 'Покемоны - спасатели должны обладать умением быстро соображать, быстро бегать и сохранять хладнокровие в самых опасных ситуациях. Их профессия важная и очень трудная.', '<div class=\"pokSELECT\" onclick=\"openDex(67)\"><img src=\"/img/pokemons/animation/067.png\">#067 Мачок</div> <div class=\"pokSELECT\" onclick=\"openDex(115)\"><img src=\"/img/pokemons/animation/115.png\">#115 Кангасхан</div><div class=\"pokSELECT\" onclick=\"openDex(217)\"><img src=\"/img/pokemons/animation/217.png\">#217 Урсаринг</div><div class=\"pokSELECT\" onclick=\"openDex(277)\"><img src=\"/img/pokemons/animation/277.png\">#277 Свилоу</div><div class=\"pokSELECT\" onclick=\"openDex(505)\"><img src=\"/img/pokemons/animation/505.png\">#505 Ватчог</div><div class=\"pokSELECT\" onclick=\"openDex(508)\"><img src=\"/img/pokemons/animation/508.png\">#508 Стотланд</div><div class=\"pokSELECT\" onclick=\"openDex(510)\"><img src=\"/img/pokemons/animation/510.png\">#510 Липард</div><div class=\"pokSELECT\" onclick=\"openDex(523)\"><img src=\"/img/pokemons/animation/523.png\">#523 Зебстрайка</div><div class=\"pokSELECT\" onclick=\"openDex(735)\"><img src=\"/img/pokemons/animation/735.png\">#735 Гамшус</div> <div class=\"pokSELECT\" onclick=\"openDex(773)\"><img src=\"/img/pokemons/animation/773.png\">#773 Силвалли</div>', 25000, 0),
(11, 'Горняк\r\n', 'Часто, люди не хотят марать руки на такой неблагодарной профессии, поэтому отправляют в опасные шахты и пещеры карманных питомцев. Они сильнее, универсальнее, да и работают охотнее. Вы сможете отправить на эту работу только очень выносливых покемонов!', '<div class=\"pokSELECT\" onclick=\"openDex(28)\"><img src=\"/img/pokemons/animation/028.png\">#028 Сендслеш</div><div class=\"pokSELECT\" onclick=\"openDex(31)\"><img src=\"/img/pokemons/animation/031.png\">#031 Нидоквин</div><div class=\"pokSELECT\" onclick=\"openDex(34)\"><img src=\"/img/pokemons/animation/034.png\">#034 Нидокинг</div> <div class=\"pokSELECT\" onclick=\"openDex(76)\"><img src=\"/img/pokemons/animation/076.png\">#076 Голем</div><div class=\"pokSELECT\" onclick=\"openDex(112)\"><img src=\"/img/pokemons/animation/112.png\">#112 Райдон</div><div class=\"pokSELECT\" onclick=\"openDex(115)\"><img src=\"/img/pokemons/animation/115.png\">#115 Кангасхан</div><div class=\"pokSELECT\" onclick=\"openDex(473)\"><img src=\"/img/pokemons/animation/473.png\">#473 Мамосвайн</div><div class=\"pokSELECT\" onclick=\"openDex(526)\"><img src=\"/img/pokemons/animation/526.png\">#526 Гигалит</div><div class=\"pokSELECT\" onclick=\"openDex(689)\"><img src=\"/img/pokemons/animation/689.png\">#689 Барбаракл</div>', 15000, 0),
(12, 'Артист\r\n', 'Развлекать народ - привилегия не одних лишь людей. Издавна покемоны служили помощниками на различных мероприятиях. Они помогали, выступали, выходили на бис наравне с тренерами. Определенное число покемонов может принимать участия в выступлениях, добавив о', '<div class=\"pokSELECT\" onclick=\"openDex(65)\"><img src=\"/img/pokemons/animation/065.png\">#065 Алаказам</div><div class=\"pokSELECT\" onclick=\"openDex(124)\"><img src=\"/img/pokemons/animation/124.png\">#124 Джинкс</div><div class=\"pokSELECT\" onclick=\"openDex(303)\"><img src=\"/img/pokemons/animation/303.png\">#303 Мавайл</div> <div class=\"pokSELECT\" onclick=\"openDex(350)\"><img src=\"/img/pokemons/animation/350.png\">#350 Милотик</div><div class=\"pokSELECT\" onclick=\"openDex(424)\"><img src=\"/img/pokemons/animation/424.png\">#424 Эмбипом</div><div class=\"pokSELECT\" onclick=\"openDex(463)\"><img src=\"/img/pokemons/animation/463.png\">#463 Ликилики</div><div class=\"pokSELECT\" onclick=\"openDex(542)\"><img src=\"/img/pokemons/animation/542.png\">#542 Ливанни</div><div class=\"pokSELECT\" onclick=\"openDex(741)\"><img src=\"/img/pokemons/animation/741.png\">#741 Орикорио</div>', 30000, 0),
(13, 'Певец\r\n', 'В наш современный век никогда не знаешь, кто из начинающих звезд взлетит на музыкальном поприще. Иногда продюсерам приходится идти на крайние меры - например, вместо людей отправлять на сцену красиво разодетых и голосистых покемонов. Всё в угоду публике!', '<div class=\"pokSELECT\" onclick=\"openDex(40)\"><img src=\"/img/pokemons/animation/040.png\">#040 Виглипафф</div> <div class=\"pokSELECT\" onclick=\"openDex(131)\"><img src=\"/img/pokemons/animation/131.png\">#131 Лапрас</div><div class=\"pokSELECT\" onclick=\"openDex(282)\"><img src=\"/img/pokemons/animation/282.png\">#282 Гардевуар</div><div class=\"pokSELECT\" onclick=\"openDex(295)\"><img src=\"/img/pokemons/animation/295.png\">#295 Эксплоуд</div> <div class=\"pokSELECT\" onclick=\"openDex(301)\"><img src=\"/img/pokemons/animation/301.png\">#301 Делкетти</div> <div class=\"pokSELECT\" onclick=\"openDex(358)\"><img src=\"/img/pokemons/animation/358.png\">#358 Чимечо</div> <div class=\"pokSELECT\" onclick=\"openDex(730)\"><img src=\"/img/pokemons/animation/730.png\">#730 Примарина</div> <div class=\"pokSELECT\" onclick=\"openDex(743)\"><img src=\"/img/pokemons/animation/743.png\">#743 Рибомби</div> <div class=\"pokSELECT\" onclick=\"openDex(763)\"><img src=\"/img/pokemons/animation/763.png\">#763 Тсарина</div>   ', 25000, 0),
(14, 'Грузчик', 'Таскать тяжелые грузы, уметь обращаться со складами, выполнять монтажные работы - вот качества хорошего покемона-грузчика. На таком месте оказываются покемоны с высокой силовой подготовкой, поэтому если хотите отдать своего питомца на такую работу, то убе', '<div class=\"pokSELECT\" onclick=\"openDex(57)\"><img src=\"/img/pokemons/animation/057.png\">#057 Праймап</div><div class=\"pokSELECT\" onclick=\"openDex(68)\"><img src=\"/img/pokemons/animation/068.png\">#068 Мачамп</div><div class=\"pokSELECT\" onclick=\"openDex(297)\"><img src=\"/img/pokemons/animation/297.png\">#297 Харияма</div> <div class=\"pokSELECT\" onclick=\"openDex(534)\"><img src=\"/img/pokemons/animation/534.png\">#534 Конкелдур</div><div class=\"pokSELECT\" onclick=\"openDex(620)\"><img src=\"/img/pokemons/animation/620.png\">#620 Миншао</div><div class=\"pokSELECT\" onclick=\"openDex(625)\"><img src=\"/img/pokemons/animation/625.png\">#625 Бишарп</div><div class=\"pokSELECT\" onclick=\"openDex(675)\"><img src=\"/img/pokemons/animation/675.png\">#675 Пангоро</div><div class=\"pokSELECT\" onclick=\"openDex(750)\"><img src=\"/img/pokemons/animation/750.png\">#750 Мадсдэйл</div>', 30000, 0);
