INSERT INTO `enc_pages` (`id`, `slug`, `title`, `grp`, `sort`, `content`, `created_at`) VALUES
(1, 'start-here', 'С чего начать', 'Основы', 10, '[b]Добро пожаловать[/b] в Poke Kara.\\n\\n• Используйте [b]Покедекс[/b] для поиска.\\n• В [b]Сборках[/b] можно сохранить команду из 6 покемонов.', '2026-01-14 21:50:41'),
(2, 'how-builds-work', 'Как работают сборки', 'Сборки', 10, 'Сборка = команда из 6 слотов.\\n\\nДоступ: [b]private[/b], [b]public[/b], [b]shared[/b].\\n\\nПопулярность покемонов считается только по [b]public[/b]-сборкам.', '2026-01-14 21:50:41'),
(3, 'bbcode', 'Форматирование (BBCode)', 'Справка', 10, 'Поддерживается базовый BBCode: [b], [i], [u], [s], [quote], [code], [url], [img].\\n\\nПример:\\n[quote=Автор]Текст[/quote]', '2026-01-14 21:50:41');
