INSERT INTO `user_notes` (`id`, `notes`) VALUES
(443, 'Обменник: \n#035 Клефейри - \n#081 Магнимайт - \n#127 Пинсир -\n#092 Гастли -\n#033 Нидорино - \nНабор тренировки «непередаваемый» - \nАмурит - \nФиолетовая конфета - '),
(464, 'Перо Муркроу x4\n Пластина Арона x2готово\n Кристалл Карбинка x3 готово\n Тлеющая грива Пониты x1 готово\n Солнечное семя Санкерна 5x готово\nСикинг, Голдинг, тентакул, поливан, псидак\nЗапись 5\nСобраны четыре ключа. Сдать снабжение: Покебол×50, Грейтбол×15, Энергетик×5, Противоядие×5, Антипарализ×5. Бонус: Громовой камень×1 (необязательно).');
