INSERT INTO `world_bosses` (`id`, `boss_id`, `location_id`, `name`, `description`, `level_min`, `level_max`, `hp_max`, `attack_power`, `defense_power`, `special_abilities`, `spawn_schedule`, `duration_minutes`, `cooldown_minutes`, `max_participants`, `base_rewards`, `rank_rewards`, `first_kill_rewards`, `is_active`, `created_at`) VALUES
(1, 150, 1, 'Мьюту Разрушитель', 'Легендарный покемон с огромной психической силой. Появляется каждые 6 часов.', 50, 100, 1000000, 2000, 800, NULL, '0 */6 * * *', 90, 360, 50, '{\"items\": [{\"id\": 1, \"count\": 2000}, {\"id\": 26, \"count\": 5}], \"money\": 5000}', '{\"top10\": [{\"id\": 83, \"count\": 1}], \"top25\": [{\"id\": 12, \"count\": 3}]}', '{\"items\": [{\"id\": 99, \"count\": 1}], \"money\": 10000}', 1, '2025-09-14 17:06:49'),
(2, 144, 2, 'Артикуно Ледяной', 'Птица льда из далёких земель. Слабее Мьюту, но всё ещё опасен.', 30, 100, 500000, 1500, 600, NULL, '0 */4 * * *', 60, 240, 30, '{\"items\": [{\"id\": 1, \"count\": 1500}, {\"id\": 83, \"count\": 1}], \"money\": 3000}', '{\"top10\": [{\"id\": 90, \"count\": 1}], \"top25\": [{\"id\": 26, \"count\": 3}]}', '{\"items\": [{\"id\": 84, \"count\": 1}], \"money\": 7000}', 1, '2025-09-14 17:06:49'),
(3, 145, 3, 'Запдос Громовой', 'Птица молний с невероятной скоростью.', 30, 100, 500000, 1700, 500, NULL, '0 */4 * * *', 60, 240, 30, '{\"items\": [{\"id\": 1, \"count\": 1500}, {\"id\": 84, \"count\": 1}], \"money\": 3000}', '{\"top10\": [{\"id\": 91, \"count\": 1}], \"top25\": [{\"id\": 26, \"count\": 3}]}', '{\"items\": [{\"id\": 85, \"count\": 1}], \"money\": 7000}', 1, '2025-09-14 17:06:49'),
(4, 150, 1, 'Тестовый Мьюту', 'Тестовый мировой босс для отладки системы рейдов', 1, 100, 500000, 1500, 600, NULL, '*/10 * * * *', 60, 10, 30, '{\"items\": [{\"id\": 1, \"count\": 15000}], \"money\": 25000}', '{\"top10\": [{\"id\": 83, \"count\": 1}]}', '{\"money\": 50000}', 1, '2025-09-14 18:47:09');
